-- ======== 07_api_informes.sql ========
-- ===================== API: informes =====================

create or replace function rodar.rango_desde(p jsonb) returns timestamp language sql immutable as $$
  select case when nullif(p ->> 'desde', '') is null then '2000-01-01'::timestamp else replace(p ->> 'desde', 'T', ' ')::timestamp end $$;
create or replace function rodar.rango_hasta(p jsonb) returns timestamp language sql immutable as $$
  select case when nullif(p ->> 'hasta', '') is null then '2999-12-31'::timestamp
              when length(p ->> 'hasta') = 10 then (p ->> 'hasta')::date + interval '1 day' - interval '1 second'
              else replace(p ->> 'hasta', 'T', ' ')::timestamp end $$;
-- móviles visibles para titulares/conductores (null = todos)
create or replace function rodar.moviles_permitidos(u rodar.usuarios) returns bigint[] language sql stable as $$
  select case when rodar.tiene(u, 'gestion', 'operador') then null else
    coalesce((select array_agg(id) from (select id from rodar.moviles where titular_id = u.id union select movil_id from rodar.movil_conductores where usuario_id = u.id) z), '{}') end $$;

create or replace function public.r_inf_acciones(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare w text;
begin
  perform rodar.need(p_token, 'gestion');
  w := format('fecha between %L and %L', rodar.rango_desde(p_q), rodar.rango_hasta(p_q));
  if rodar.t(p_q, 'tipo') is not null then w := w || format(' and tipo = %L', p_q ->> 'tipo'); end if;
  if coalesce(rodar.n(p_q, 'actor'), 0) > 0 then w := w || format(' and actor_id = %s', rodar.n(p_q, 'actor')); end if;
  if rodar.t(p_q, 'buscar') is not null then w := w || format(' and (afectado ilike %1$L or actor ilike %1$L or detalle ilike %1$L or tipo ilike %1$L)', '%' || (p_q ->> 'buscar') || '%'); end if;
  return rodar.lista('select * from rodar.acciones_usuarios where ' || w || ' order by id desc limit 2000');
end $$;
create or replace function public.r_inf_eventos(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare w text;
begin
  perform rodar.need(p_token, 'gestion');
  w := format('fecha between %L and %L', rodar.rango_desde(p_q), rodar.rango_hasta(p_q));
  if rodar.t(p_q, 'tipo') is not null then w := w || format(' and tipo = %L', p_q ->> 'tipo'); end if;
  if coalesce(rodar.n(p_q, 'movil'), 0) > 0 then w := w || format(' and movil_numero = %s', rodar.n(p_q, 'movil')); end if;
  return rodar.lista('select * from rodar.eventos_moviles where ' || w || ' order by id desc limit 3000');
end $$;
create or replace function public.r_inf_bloqueados(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

begin
  perform rodar.need(p_token, 'operador', 'gestion');
  return rodar.lista('select c.id, c.telefono, c.alias, c.motivo_bloqueo motivo, trim(u.nombre || '' '' || coalesce(u.apellido, '''')) bloqueado_por, c.bloqueado_at fecha from rodar.clientes c left join rodar.usuarios u on u.id = c.bloqueado_por where c.bloqueado order by c.bloqueado_at desc nulls last');
end $$;
create or replace function public.r_inf_baja(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

begin
  perform rodar.need(p_token, 'operador', 'gestion');
  return rodar.lista('select c.id, c.telefono, c.alias, c.baja_at, trim(u.nombre || '' '' || coalesce(u.apellido, '''')) quien, c.baja_at + interval ''7 days'' purga from rodar.clientes c left join rodar.usuarios u on u.id = c.baja_por where c.baja_at is not null order by c.baja_at desc');
end $$;
create or replace function public.r_inf_conductores(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare d timestamp := rodar.rango_desde(p_q); h timestamp := rodar.rango_hasta(p_q);
begin
  perform rodar.need(p_token, 'gestion');
  return rodar.lista(format($q$select u.id, u.foto, u.documento, trim(u.nombre || ' ' || coalesce(u.apellido, '')) nombre,
    (select count(*) from rodar.viajes where conductor_id = u.id and estado = 'finalizado' and creado between %1$L and %2$L) viajes,
    (select coalesce(sum(monto), 0) from rodar.viajes where conductor_id = u.id and estado = 'finalizado' and creado between %1$L and %2$L) ingresos,
    (select round(coalesce(sum(segundos), 0) / 3600.0, 1) from rodar.conexion_diaria where usuario_id = u.id and tipo = 'app' and fecha between %1$L::date and %2$L::date) horas,
    (select round(avg(calificacion), 2) from rodar.viajes where conductor_id = u.id and calificacion is not null and creado between %1$L and %2$L) calificacion,
    (select count(*) from rodar.eventos_moviles e where e.tipo in ('timeout', 'rechazado_movil') and e.fecha between %1$L and %2$L and e.movil_id in (select movil_id from rodar.movil_conductores where usuario_id = u.id)) no_respondidos
    from rodar.usuarios u where 'conductor' = any(string_to_array(u.roles, ',')) order by viajes desc$q$, d, h));
end $$;
create or replace function public.r_inf_conectados(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare w text := 's.activa and s.ultimo >= rodar.ahora() - interval ''30 minutes''';
begin
  perform rodar.need(p_token, 'admin');
  if rodar.t(p_q, 'tipo') is not null then w := w || format(' and s.tipo = %L', p_q ->> 'tipo'); end if;
  if rodar.t(p_q, 'buscar') is not null then w := w || format(' and ((u.nombre || '' '' || u.apellido) ilike %1$L or u.documento ilike %1$L)', '%' || (p_q ->> 'buscar') || '%'); end if;
  return rodar.lista('select left(s.token, 8) token, s.tipo, s.inicio, s.ultimo, s.ip, s.cooldown_hasta, u.id usuario_id, trim(u.nombre || '' '' || coalesce(u.apellido, '''')) usuario, u.documento, u.roles, m.numero movil,
      (select round(coalesce(sum(segundos), 0) / 60) from rodar.conexion_diaria where usuario_id = u.id and fecha = rodar.hoy() and tipo = s.tipo) min_hoy
      from rodar.sesiones s join rodar.usuarios u on u.id = s.usuario_id left join rodar.moviles m on m.id = s.movil_id where ' || w || ' order by s.inicio desc')
    || case when coalesce(p_q ->> 'tipo', '') = 'web' then '[]'::jsonb else rodar.lista(format('select ''app'' tipo, trim(u.nombre || '' '' || coalesce(u.apellido, '''')) usuario, u.documento, u.roles, m.numero movil, ''simulado'' ip
      from rodar.moviles m join rodar.usuarios u on u.id = m.conductor_id where m.simulado and m.estado <> ''desconectado'' and (u.nombre || '' '' || u.apellido) ilike %L', '%' || coalesce(p_q ->> 'buscar', '') || '%')) end;
end $$;
create or replace function public.r_inf_conectado_op(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.need(p_token, 'admin'); s rodar.sesiones;
begin
  select * into s from rodar.sesiones where token like (p_q ->> 'tk') || '%';
  if not found then raise exception 'Sesión no encontrada'; end if;
  if p_q ->> 'op' = 'cerrar' then update rodar.sesiones set activa = false where token = s.token; end if;
  if p_q ->> 'op' = 'cooldown' then update rodar.sesiones set activa = false, cooldown_hasta = rodar.ahora() + make_interval(mins => coalesce(rodar.n(p_b, 'minutos'), 15)::int) where token = s.token; end if;
  if s.movil_id is not null then perform rodar.emit('movil-' || s.movil_id, 'forzar_salida', '{}'); end if;
  perform rodar.accion(u, 'sesion_cerrada', s.usuario_id::text, p_q ->> 'op');
  return '{"ok":true}';
end $$;
create or replace function public.r_inf_estadisticas(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

begin
  perform rodar.need(p_token, 'gestion');
  return rodar.lista(format($q$select m.numero movil, trim(u.nombre || ' ' || coalesce(u.apellido, '')) conductor, count(*) filter (where v.origen_tipo = 'central') central,
    count(*) filter (where v.origen_tipo = 'calle') calle, count(*) total from rodar.viajes v join rodar.moviles m on m.id = v.movil_id left join rodar.usuarios u on u.id = v.conductor_id
    where v.estado = 'finalizado' and to_char(v.creado, 'YYYY-MM') = %L group by m.numero, u.id order by total desc$q$, coalesce(rodar.t(p_q, 'mes'), to_char(rodar.hoy(), 'YYYY-MM'))));
end $$;
create or replace function public.r_inf_horas(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

begin
  perform rodar.need(p_token, 'gestion');
  return rodar.lista(format($q$select u.documento, trim(u.nombre || ' ' || coalesce(u.apellido, '')) conductor, round(sum(c.segundos) / 3600.0, 1) horas from rodar.conexion_diaria c join rodar.usuarios u on u.id = c.usuario_id
    where c.tipo = 'app' and to_char(c.fecha, 'YYYY-MM') = %L group by u.id order by horas desc$q$, coalesce(rodar.t(p_q, 'mes'), to_char(rodar.hoy(), 'YYYY-MM'))));
end $$;
create or replace function public.r_inf_facturacion(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare mes text := coalesce(rodar.t(p_q, 'anio'), to_char(rodar.hoy(), 'YYYY')) || '-' || lpad(coalesce(rodar.t(p_q, 'mes'), to_char(rodar.hoy(), 'MM')), 2, '0'); hab int; packs jsonb; w text;
begin
  perform rodar.need(p_token, 'gestion');
  hab := greatest((select count(*) from rodar.moviles where habilitado), (select count(distinct movil_id) from rodar.viajes where to_char(creado, 'YYYY-MM') = mes));
  select coalesce(jsonb_agg(jsonb_build_object('pack', nombre, 'bonif', 0, 'qty', q, 'unitario', precio, 'monto', q * precio)), '[]') into packs
    from (select *, case when unidad = 'móvil' then hab when unidad = 'puesto' then cantidad else 1 end q from rodar.modulos where activo) z;
  w := format('to_char(fecha, ''YYYY-MM'') = %L', mes);
  if coalesce(rodar.n(p_q, 'numero'), 0) > 0 then w := w || format(' and movil_numero = %s', rodar.n(p_q, 'numero')); end if;
  return jsonb_build_object('mes', mes, 'packs', packs, 'total', (select coalesce(sum((x ->> 'monto')::numeric), 0) from jsonb_array_elements(packs) x), 'habilitados', hab,
    'moviles', rodar.lista(format($q$select numero movil, horas, viajes_central, case when horas > 0 then 'SI' else 'NO' end conectado, case when viajes_central > 0 then 'SI' else 'NO' end con_viaje,
      case when habilitado then '' else 'Inhabilitado' end exclusion from (select m.numero, m.habilitado,
      (select round(coalesce(sum(c.segundos), 0) / 3600.0, 1) from rodar.conexion_diaria c where c.tipo = 'app' and to_char(c.fecha, 'YYYY-MM') = %1$L and c.usuario_id in (select usuario_id from rodar.movil_conductores where movil_id = m.id)) horas,
      (select count(*) from rodar.viajes v where v.movil_id = m.id and v.origen_tipo = 'central' and v.estado = 'finalizado' and to_char(v.creado, 'YYYY-MM') = %1$L) viajes_central
      from rodar.moviles m) z order by numero$q$, mes)),
    'log', rodar.lista('select * from rodar.moviles_historial where ' || w || ' order by id desc'));
end $$;
create or replace function public.r_inf_movimientos(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare w text;
begin
  perform rodar.need(p_token, 'gestion');
  w := format('fecha between %L and %L', rodar.rango_desde(p_q), rodar.rango_hasta(p_q));
  if coalesce(rodar.n(p_q, 'numero'), 0) > 0 then w := w || format(' and movil_numero = %s', rodar.n(p_q, 'numero')); end if;
  return rodar.lista('select * from rodar.moviles_historial where ' || w || ' order by id desc');
end $$;
create or replace function public.r_inf_recorrido(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); vid bigint := rodar.n(p_q, 'movil')::bigint; perm bigint[]; d timestamp := rodar.rango_desde(p_q); h timestamp := rodar.rango_hasta(p_q); pts jsonb; est jsonb;
begin
  perm := rodar.moviles_permitidos(u);
  if perm is not null and not (vid = any(perm)) then raise exception 'Sin permiso'; end if;
  pts := rodar.lista(format('select ts, lat, lng, estado, velocidad from rodar.posiciones where movil_id = %s and ts between %L and %L %s order by ts limit 20000', vid, d, h, case when p_q ->> 'emergencias' = '1' then ' and estado = ''emergencia''' else '' end));
  with p as (select (x ->> 'ts')::timestamp ts, (x ->> 'lat')::float8 lat, (x ->> 'lng')::float8 lng, x ->> 'estado' estado from jsonb_array_elements(pts) x),
  s as (select estado, lat, lng, ts, lead(lat) over (order by ts) lat2, lead(lng) over (order by ts) lng2, lead(ts) over (order by ts) ts2 from p),
  g as (select estado, sum(rodar.dist(lat, lng, lat2, lng2)) / 1000 km, sum(extract(epoch from ts2 - ts)) / 3600 horas from s where ts2 is not null and extract(epoch from ts2 - ts) <= 600 group by estado)
  select coalesce(jsonb_object_agg(estado, jsonb_build_object('km', round(km::numeric, 2), 'horas', round(horas::numeric, 2))), '{}') into est from g;
  return jsonb_build_object('puntos', pts, 'eventos', rodar.lista(format('select * from rodar.eventos_moviles where movil_id = %s and fecha between %L and %L order by id', vid, d, h)), 'porEstado', est);
end $$;
create or replace function public.r_inf_mensual(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare mes text := coalesce(rodar.t(p_q, 'anio'), to_char(rodar.hoy(), 'YYYY')) || '-' || lpad(coalesce(rodar.t(p_q, 'mes'), to_char(rodar.hoy(), 'MM')), 2, '0');
  viajes int; conv int; cnx int; canales jsonb; tipos jsonb; parada int; canc int; rango int; hist jsonb;
begin
  perform rodar.need(p_token, 'gestion');
  select count(*), count(distinct movil_id), count(*) filter (where parada_id is not null) into viajes, conv, parada from rodar.viajes where estado = 'finalizado' and to_char(creado, 'YYYY-MM') = mes;
  select count(distinct usuario_id) into cnx from rodar.conexion_diaria where tipo = 'app' and to_char(fecha, 'YYYY-MM') = mes;
  select coalesce(jsonb_object_agg(canal, c), '{}') into canales from (select canal, count(*) c from rodar.viajes where estado = 'finalizado' and to_char(creado, 'YYYY-MM') = mes group by canal) z;
  select coalesce(jsonb_object_agg(origen_tipo, c), '{}') into tipos from (select origen_tipo, count(*) c from rodar.viajes where estado = 'finalizado' and to_char(creado, 'YYYY-MM') = mes group by origen_tipo) z;
  select count(*) into canc from rodar.viajes where estado = 'anulado' and to_char(creado, 'YYYY-MM') = mes;
  rango := case coalesce(p_q ->> 'rango', '12') when '24' then 24 when '36' then 36 when 'todo' then 999 else 12 end;
  hist := rodar.lista(format('select * from (select to_char(creado, ''YYYY-MM'') mes, count(*) c from rodar.viajes where estado = ''finalizado'' group by 1 order by 1 desc limit %s) z order by mes', rango));
  return jsonb_build_object('mes', mes, 'viajes', viajes, 'por_movil', case when conv > 0 then round(viajes::numeric / conv, 1) else 0 end, 'con_viaje', conv, 'conectados', cnx,
    'desglose', jsonb_build_object('central', coalesce((tipos ->> 'central')::int, 0), 'calle', coalesce((tipos ->> 'calle')::int, 0), 'telefonica', coalesce((canales ->> 'centralita')::int, 0),
      'whatsapp', coalesce((canales ->> 'whatsapp')::int, 0), 'app', coalesce((canales ->> 'aplicacion')::int, 0) + coalesce((canales ->> 'web')::int, 0), 'telegram', coalesce((canales ->> 'telegram')::int, 0),
      'parada', parada, 'domicilio', coalesce((tipos ->> 'central')::int, 0) - parada, 'cancelados', canc),
    'diario', rodar.lista(format('select to_char(creado, ''DD'') dia, count(*) c from rodar.viajes where estado = ''finalizado'' and to_char(creado, ''YYYY-MM'') = %L group by 1 order by 1', mes)),
    'historico', hist, 'media', (select coalesce(round(avg((x ->> 'c')::numeric), 1), 0) from jsonb_array_elements(hist) x));
end $$;
create or replace function public.r_inf_operadores(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

begin
  perform rodar.need(p_token, 'gestion');
  return rodar.lista(format($q$select trim(u.nombre || ' ' || coalesce(u.apellido, '')) operador, u.documento, sum(c.cargados) cargados, round(sum(c.segundos) / 3600.0, 2) horas
    from rodar.conexion_diaria c join rodar.usuarios u on u.id = c.usuario_id where c.tipo = 'web' and c.fecha between %L and %L and 'operador' = any(string_to_array(u.roles, ',')) group by u.id order by cargados desc$q$,
    coalesce(rodar.t(p_q, 'desde')::date, rodar.hoy()), coalesce(rodar.t(p_q, 'hasta')::date, rodar.hoy())));
end $$;
create or replace function public.r_inf_demanda(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare a timestamp := rodar.ahora(); dia int; desde int;
begin
  perform rodar.usuario(p_token);
  dia := coalesce(rodar.n(p_q, 'dia')::int, extract(dow from a)::int);
  desde := coalesce(rodar.n(p_q, 'hora')::int * 60, extract(hour from a)::int * 60 + case when extract(minute from a) < 30 then 0 else 30 end);
  return jsonb_build_object('dia', dia, 'desde', desde, 'puntos', rodar.lista(format($q$select origen_lat lat, origen_lng lng from rodar.viajes where origen_lat is not null and creado >= rodar.ahora() - interval '90 days'
    and extract(dow from creado) = %s and (extract(hour from creado) * 60 + extract(minute from creado)) between %s and %s$q$, dia, desde - 30, desde + 60)));
end $$;
create or replace function public.r_inf_calor(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

begin
  perform rodar.need(p_token, 'gestion');
  return rodar.lista(format('select lat, lng from rodar.posiciones where ts >= rodar.ahora() - make_interval(hours => %s) and id %% 3 = 0 limit 15000', least(168, coalesce(rodar.n(p_q, 'horas'), 6))::int));
end $$;
create or replace function public.r_inf_negativos(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare mid bigint;
begin
  perform rodar.need(p_token, 'operador', 'gestion');
  select id into mid from rodar.moviles where numero = rodar.n(p_q, 'movil');
  if mid is null then return '[]'; end if;
  return rodar.lista('select c.id cliente_id, c.telefono, c.alias, (select direccion from rodar.cliente_domicilios where cliente_id = c.id order by usos desc limit 1) domicilio from rodar.negativos n join rodar.clientes c on c.id = n.cliente_id where n.movil_id = ' || mid);
end $$;
create or replace function public.r_inf_top10(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare r jsonb := '{}'; d int;
begin
  perform rodar.usuario(p_token);
  foreach d in array array[1, 7, 30] loop
    r := r || jsonb_build_object(d::text, rodar.lista(format($q$select trim(u.nombre || ' ' || coalesce(u.apellido, '')) conductor, m.numero movil, count(*) viajes from rodar.viajes v join rodar.usuarios u on u.id = v.conductor_id
      join rodar.moviles m on m.id = v.movil_id where v.estado = 'finalizado' and v.creado >= rodar.ahora() - interval '%s days' group by u.id, m.numero order by viajes desc limit 10$q$, d)));
  end loop;
  return r;
end $$;
create or replace function public.r_inf_viajes_movil(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); perm bigint[]; w text; f jsonb;
begin
  w := format('v.estado = ''finalizado'' and v.creado between %L and %L', rodar.rango_desde(p_q), rodar.rango_hasta(p_q));
  perm := rodar.moviles_permitidos(u);
  if rodar.tiene(u, 'corporativo') and not rodar.tiene(u, 'gestion', 'operador') then w := w || format(' and v.corporativo_id = %s', coalesce(u.corporativo_id, -1));
  elsif perm is not null then
    w := w || format(' and v.movil_id = any(%L::bigint[])', perm);
    if not rodar.tiene(u, 'titular') then w := w || format(' and v.conductor_id = %s', u.id); end if;
  end if;
  if coalesce(rodar.n(p_q, 'movil'), 0) > 0 then w := w || format(' and m.numero = %s', rodar.n(p_q, 'movil')); end if;
  if p_q ->> 'tipo' = 'central' then w := w || ' and v.origen_tipo = ''central'''; end if;
  if p_q ->> 'tipo' = 'calle' then w := w || ' and v.origen_tipo = ''calle'''; end if;
  if p_q ->> 'tipo' = 'corporativos' then w := w || ' and v.corporativo_id is not null'; end if;
  f := rodar.lista('select v.id, v.creado fecha, m.numero movil, v.origen_dir, v.destino_dir, v.km, v.minutos, v.monto, v.medio_pago pago, v.origen_tipo from rodar.viajes v join rodar.moviles m on m.id = v.movil_id where ' || w || ' order by v.id desc limit 5000');
  return jsonb_build_object('filas', f, 'totales', (select jsonb_build_object('viajes', count(*), 'monto', coalesce(sum((x ->> 'monto')::numeric), 0), 'moviles', count(distinct x ->> 'movil')) from jsonb_array_elements(f) x));
end $$;
create or replace function public.r_inf_rendimiento(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); d timestamp := rodar.rango_desde(p_q); h timestamp := rodar.rango_hasta(p_q); r jsonb; e jsonb; horas numeric;
begin
  select jsonb_build_object('viajes', count(*), 'ingresos', coalesce(sum(monto), 0), 'calificacion', round(avg(calificacion), 2), 'km', round(coalesce(sum(km), 0), 1)) into r
    from rodar.viajes where conductor_id = u.id and estado = 'finalizado' and creado between d and h;
  select coalesce(jsonb_object_agg(tipo, c), '{}') into e from (select tipo, count(*) c from rodar.eventos_moviles where movil_id in (select movil_id from rodar.movil_conductores where usuario_id = u.id)
    and fecha between d and h and tipo in ('ofrecido', 'aceptado', 'rechazado_movil', 'timeout') group by tipo) z;
  select round(coalesce(sum(segundos), 0) / 3600.0, 1) into horas from rodar.conexion_diaria where usuario_id = u.id and tipo = 'app' and fecha between d::date and h::date;
  return r || jsonb_build_object('horas', horas, 'ofrecidos', coalesce((e ->> 'ofrecido')::int, 0), 'aceptados', coalesce((e ->> 'aceptado')::int, 0), 'rechazados', coalesce((e ->> 'rechazado_movil')::int, 0),
    'sin_respuesta', coalesce((e ->> 'timeout')::int, 0), 'respuesta', case when coalesce((e ->> 'ofrecido')::int, 0) > 0 then round(coalesce((e ->> 'aceptado')::int, 0) * 100.0 / (e ->> 'ofrecido')::int) end,
    'por_hora', case when horas > 0 then round((r ->> 'ingresos')::numeric / horas) else 0 end);
end $$;
create or replace function public.r_inf_mis_vehiculos(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); perm bigint[] := rodar.moviles_permitidos(u);
begin
  return coalesce((select jsonb_agg(rodar.movil_publico(m) order by m.numero) from rodar.moviles m where perm is null or m.id = any(perm)), '[]');
end $$;


-- ======== 08_api_apps.sql ========
-- ===================== API: app de conductores, pedido web, carga de saldo =====================

create or replace function rodar.movil_sesion(p_token text) returns rodar.moviles language plpgsql as $$
#variable_conflict use_variable

declare s rodar.sesiones; m rodar.moviles;
begin
  perform rodar.usuario(p_token);
  select * into s from rodar.sesiones where token = p_token;
  if s.movil_id is null then raise exception 'Sesión sin móvil'; end if;
  select * into m from rodar.moviles where id = s.movil_id;
  return m;
end $$;

create or replace function public.r_cond_moviles(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios; us text := trim(coalesce(p_b ->> 'usuario', '')); cd timestamp;
begin
  select * into u from rodar.usuarios where (usuario = us or documento = us) and habilitado;
  if not found or not rodar.verificar(coalesce(p_b ->> 'password', ''), u.password_hash) then raise exception 'Usuario o contraseña incorrectos'; end if;
  if not rodar.tiene(u, 'conductor', 'titular') then raise exception 'El usuario no es conductor'; end if;
  select max(cooldown_hasta) into cd from rodar.sesiones where usuario_id = u.id;
  if cd > rodar.ahora() then raise exception 'Sesión suspendida hasta %', to_char(cd, 'HH24:MI'); end if;
  return rodar.lista('select m.id, m.numero, m.patente, m.estado, m.conductor_id from rodar.moviles m join rodar.movil_conductores mc on mc.movil_id = m.id where mc.usuario_id = ' || u.id || ' and m.habilitado order by m.numero');
end $$;

create or replace function public.r_cond_iniciar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); m rodar.moviles := rodar.movil_sesion(p_token);
begin
  if not exists(select 1 from rodar.movil_conductores where movil_id = m.id and usuario_id = u.id) then raise exception 'No estás asignado a ese móvil'; end if;
  if m.conductor_id is not null and m.conductor_id <> u.id and m.estado <> 'desconectado' and not m.simulado then raise exception 'Otro conductor está usando el móvil'; end if;
  update rodar.moviles set conductor_id = u.id, simulado = false, estado = case when estado = 'desconectado' then 'disponible' else estado end where id = m.id;
  delete from rodar.sim_estado where movil_id = m.id;
  perform rodar.evento_movil(m.id, 'login', null, 'Ingreso ' || rodar.nombre(u));
  perform rodar.emitir_movil(m.id);
  return '{"ok":true}';
end $$;

create or replace function public.r_cond_estado(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); m rodar.moviles := rodar.movil_sesion(p_token); vid bigint; t rodar.tarifas;
begin
  perform rodar.procesar();
  select id into vid from rodar.viajes where movil_id = m.id and estado in ('ofrecido', 'confirmado', 'en_curso') order by id desc limit 1;
  t := rodar.tarifa_vigente();
  return jsonb_build_object('movil', rodar.movil_publico(m), 'conductor', jsonb_build_object('nombre', u.nombre, 'apellido', u.apellido, 'documento', u.documento),
    'viaje', case when vid is not null then rodar.viaje_detalle(vid) end,
    'paradas', coalesce((select jsonb_agg(jsonb_build_object('id', z.id, 'nombre', z.nombre, 'lat', z.parada_lat, 'lng', z.parada_lng,
        'cola', coalesce((select jsonb_agg(x.numero order by x.parada_ingreso) from rodar.moviles x where x.estado = 'en_parada' and x.parada_id = z.id), '[]')) order by z.orden) from rodar.zonas z where z.es_parada), '[]'),
    'tarifa', case when t.id is null then null else to_jsonb(t) end, 'saldo', rodar.saldo(m.id), 'cuenta', rodar.estado_cuenta(m),
    'zonas', rodar.lista('select * from rodar.zonas order by orden'), 'peligrosas', rodar.lista('select * from rodar.zonas_peligrosas'),
    'empresa', rodar.cfg('empresa'), 'mensajes', rodar.lista('select * from rodar.mensajes_flota order by id desc limit 5'), 'canal', rodar.topico(''),
    'abiertas', coalesce((select jsonb_agg(jsonb_build_object('id', v.id, 'origen_dir', v.origen_dir, 'zona', z.nombre, 'destino_dir', v.destino_dir) order by v.id)
      from rodar.viajes v left join rodar.zonas z on z.id = v.zona_id where v.estado = 'pendiente' and v.a_oferta and rodar.elegible(m, v)), '[]'));
end $$;

create or replace function public.r_cond_set_estado(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); m rodar.moviles := rodar.movil_sesion(p_token); e text := p_b ->> 'estado';
begin
  if e not in ('disponible', 'fuera_servicio', 'en_parada', 'emergencia') then raise exception 'Estado inválido'; end if;
  if m.estado in ('confirmado', 'con_pasajero') and e <> 'emergencia' then raise exception 'Tenés un viaje en curso'; end if;
  perform rodar.set_estado_movil(m.id, e, rodar.n(p_b, 'parada_id')::bigint, false);
  if e = 'fuera_servicio' then perform rodar.evento_movil(m.id, 'fuera_servicio', null, 'Fuera de servicio'); end if;
  if e = 'emergencia' then
    perform rodar.evento_movil(m.id, 'emergencia', null, 'BOTÓN DE EMERGENCIA');
    insert into rodar.posiciones(movil_id, ts, lat, lng, estado) values (m.id, rodar.ahora(), m.lat, m.lng, 'emergencia');
    perform rodar.emit('panel', 'emergencia', jsonb_build_object('movil', m.numero, 'lat', m.lat, 'lng', m.lng, 'conductor', rodar.nombre(u)));
  end if;
  perform rodar.procesar();
  return '{"ok":true}';
end $$;

create or replace function public.r_cond_posicion(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare m rodar.moviles := rodar.movil_sesion(p_token); lat float8 := (p_b ->> 'lat')::float8; lng float8 := (p_b ->> 'lng')::float8; z rodar.zonas;
begin
  if lat is null then return '{"ok":true}'; end if;
  perform rodar.posicion(m.id, lat, lng, (p_b ->> 'vel')::float8, (p_b ->> 'rumbo')::float8, true);
  -- las posiciones no se emiten por tiempo real (ahorra mensajes): el mapa las consulta cada pocos segundos
  if m.estado = 'en_parada' then z := rodar.zona_de(lat, lng); if z.id is distinct from m.parada_id then perform rodar.set_estado_movil(m.id, 'disponible'); end if; end if;
  perform rodar.procesar();
  return jsonb_build_object('ok', true, 'peligrosa', rodar.peligrosa(lat, lng));
end $$;

create or replace function public.r_cond_viaje(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); m rodar.moviles := rodar.movil_sesion(p_token); vid bigint := (p_q ->> 'id')::bigint; op text := p_q ->> 'op';
begin
  if op in ('aceptar', 'postular') then perform rodar.aceptar(vid, m.id);
  elsif op = 'rechazar' then perform rodar.rechazar(vid, m.id); perform rodar.procesar();
  elsif op = 'llegue' then perform rodar.llegada(vid);
  elsif op = 'iniciar' then perform rodar.iniciar(vid, p_b ->> 'pin');
  elsif op = 'finalizar' then
    return rodar.finalizar(vid, coalesce(rodar.n(p_b, 'metros'), 0), coalesce(rodar.n(p_b, 'esperaSeg'), 0), rodar.n(p_b, 'monto'), (p_b ->> 'lat')::float8, (p_b ->> 'lng')::float8, rodar.t(p_b, 'destino_dir'));
  elsif op = 'cancelar' then perform rodar.anular(vid, u, 'Cancelado por el conductor: ' || coalesce(p_b ->> 'motivo', ''));
  else raise exception 'Operación desconocida'; end if;
  return rodar.viaje_detalle(vid);
end $$;

create or replace function public.r_cond_calle(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); m rodar.moviles := rodar.movil_sesion(p_token); ids bigint[]; p text;
begin
  if m.estado not in ('disponible', 'en_parada') then raise exception 'Tenés que estar Libre o en Parada'; end if;
  ids := rodar.crear_viaje(jsonb_build_object('origen_dir', coalesce(rodar.t(p_b, 'origen_dir'), 'Viaje de calle'), 'origen_lat', m.lat, 'origen_lng', m.lng, 'destino_dir', p_b ->> 'destino_dir',
    'destino_lat', p_b -> 'destino_lat', 'destino_lng', p_b -> 'destino_lng', 'canal', 'movil', 'origen_tipo', 'calle', 'alias', 'CALLE', 'estado', 'pendiente', 'movil_id', m.id, 'conductor_id', u.id, 'pin_requerido', false), null);
  if m.estado = 'en_parada' then update rodar.viajes set parada_id = m.parada_id where id = ids[1]; end if;
  perform rodar.aceptar(ids[1], m.id);
  select pin into p from rodar.viajes where id = ids[1];
  perform rodar.iniciar(ids[1], p);
  return rodar.viaje_detalle(ids[1]);
end $$;

create or replace function public.r_cond_viajes(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token);
begin return rodar.lista('select id, creado, origen_dir, destino_dir, monto, km, estado, medio_pago from rodar.viajes where conductor_id = ' || u.id || ' and creado >= rodar.ahora() - interval ''7 days'' order by id desc limit 100'); end $$;
create or replace function public.r_cond_movimientos(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare m rodar.moviles := rodar.movil_sesion(p_token);
begin return jsonb_build_object('saldo', rodar.saldo(m.id), 'movimientos', rodar.lista('select * from rodar.cuenta_movimientos where movil_id = ' || m.id || ' order by id desc limit 60')); end $$;
create or replace function public.r_cond_soporte(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare m rodar.moviles := rodar.movil_sesion(p_token); cid bigint;
begin
  select id into cid from rodar.soporte_conv where tipo = 'movil' and movil_id = m.id order by id desc limit 1;
  if cid is null then return '[]'; end if;
  return rodar.lista('select * from rodar.soporte_msg where conv_id = ' || cid || ' order by id');
end $$;
create or replace function public.r_cond_soporte_enviar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare m rodar.moviles := rodar.movil_sesion(p_token); cid bigint;
begin
  select id into cid from rodar.soporte_conv where tipo = 'movil' and movil_id = m.id and not cerrada order by id desc limit 1;
  if cid is null then insert into rodar.soporte_conv(tipo, movil_id, asunto, actualizado) values ('movil', m.id, 'Consulta app conductor', rodar.ahora()) returning id into cid; end if;
  insert into rodar.soporte_msg(conv_id, de, texto, fecha) values (cid, 'movil', p_b ->> 'texto', rodar.ahora());
  update rodar.soporte_conv set no_leidos = no_leidos + 1, actualizado = rodar.ahora() where id = cid;
  perform rodar.emit('panel', 'soporte', jsonb_build_object('conv', cid));
  return '{"ok":true}';
end $$;
create or replace function public.r_cond_salir(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare m rodar.moviles := rodar.movil_sesion(p_token);
begin
  update rodar.moviles set estado = 'desconectado', conductor_id = null, parada_id = null where id = m.id and estado not in ('confirmado', 'con_pasajero');
  update rodar.sesiones set activa = false where token = p_token;
  perform rodar.evento_movil(m.id, case when rodar.b(p_b, 'cerrar_app') then 'cerroapp' else 'logout' end, null, case when rodar.b(p_b, 'cerrar_app') then 'Cerró la app' else 'Cambio de conductor / salida' end);
  perform rodar.emitir_movil(m.id);
  return '{"ok":true}';
end $$;

-- Carga de saldo (conductor desde la app o titular desde el panel). Queda pendiente hasta que se acredita.
create or replace function public.r_cargar_saldo(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); s rodar.sesiones := rodar.sesion(p_token); m rodar.moviles; monto numeric := rodar.n(p_b, 'monto'); nid bigint; mp jsonb := rodar.cfg('mp', '{}');
begin
  select * into m from rodar.moviles where id = coalesce(s.movil_id, rodar.n(p_b, 'movil_id')::bigint);
  if not found then raise exception 'Elegí un móvil'; end if;
  if not (m.titular_id = u.id or exists(select 1 from rodar.movil_conductores where movil_id = m.id and usuario_id = u.id) or rodar.tiene(u, 'admin')) then raise exception 'Sin permiso sobre ese móvil'; end if;
  if coalesce(monto, 0) <= 0 then raise exception 'Monto inválido'; end if;
  insert into rodar.mp_pagos(tipo, movil_id, monto, estado, fecha) values ('recarga', m.id, monto, 'pendiente', rodar.ahora()) returning id into nid;
  return jsonb_build_object('id', nid, 'link', nullif(mp ->> 'link_pago', ''), 'alias', nullif(mp ->> 'alias_cobro', ''),
    'mensaje', 'La carga #' || nid || ' quedó pendiente. ' || case when coalesce(mp ->> 'alias_cobro', '') <> '' then 'Transferí a ' || (mp ->> 'alias_cobro') || ' indicando la carga #' || nid || '. ' else '' end ||
      'Cuando la central confirme el pago se acredita en tu cuenta.');
end $$;

-- Solicitud de alta de conductor (pública)
create or replace function public.r_solicitud_conductor(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

begin
  if rodar.t(p_b, 'nombre') is null or rodar.t(p_b, 'dni') is null or rodar.t(p_b, 'telefono') is null then raise exception 'Completá nombre, DNI y teléfono'; end if;
  if (select count(*) from rodar.solicitudes_conductor where fecha > rodar.ahora() - interval '1 hour') > 30 then raise exception 'Demasiadas solicitudes, probá más tarde'; end if;
  insert into rodar.solicitudes_conductor(nombre, apellido, dni, telefono, email, patente, marca, modelo, anio, origen, docs, fecha)
  values (p_b ->> 'nombre', p_b ->> 'apellido', p_b ->> 'dni', p_b ->> 'telefono', p_b ->> 'email', p_b ->> 'patente', p_b ->> 'marca', p_b ->> 'modelo', rodar.n(p_b, 'anio')::int, coalesce(rodar.t(p_b, 'origen'), 'web'), coalesce((p_b -> 'docs')::text, '[]'), rodar.ahora());
  perform rodar.emit('panel', 'aviso', jsonb_build_object('texto', 'Nueva solicitud de alta de conductor: ' || (p_b ->> 'nombre') || ' ' || coalesce(p_b ->> 'apellido', '')));
  return '{"ok":true}';
end $$;

-- ================= Pasajero (público) =================
create or replace function public.r_pub_config(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare e jsonb := rodar.cfg('empresa', '{}');
begin
  return jsonb_build_object('nombre', e ->> 'nombre', 'lat', e -> 'lat', 'lng', e -> 'lng', 'telefono', e ->> 'telefono', 'localidad', e ->> 'localidad', 'provincia', e ->> 'provincia',
    'medios', rodar.lista('select codigo, nombre from rodar.medios_pago where habilitado and codigo not in (''cuenta_corriente'') order by orden'));
end $$;
create or replace function public.r_pub_estimar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

begin
  if p_b ->> 'origen_lat' is null then return 'null'; end if;
  return rodar.estimar((p_b ->> 'origen_lat')::float8, (p_b ->> 'origen_lng')::float8, (p_b ->> 'destino_lat')::float8, (p_b ->> 'destino_lng')::float8, 'web', rodar.t(p_b, 'medio_pago'), rodar.n(p_b, 'metros_ruta')::float8);
end $$;
create or replace function public.r_pub_viaje(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare tel text := regexp_replace(coalesce(p_b ->> 'telefono', ''), '\D', '', 'g'); corp bigint; medio text := coalesce(rodar.t(p_b, 'medio_pago'), 'efectivo'); ids bigint[]; s rodar.usuarios;
begin
  if (select count(*) from rodar.limite_pedidos where clave = tel and ts > now() - interval '10 minutes') >= 5 then raise exception 'Demasiados pedidos seguidos. Esperá unos minutos o llamá a la central.'; end if;
  if (select count(*) from rodar.limite_pedidos where ts > now() - interval '1 minute') >= 40 then raise exception 'Hay demasiados pedidos en este momento, probá en un minuto.'; end if;
  insert into rodar.limite_pedidos(clave) values (tel);
  if length(tel) < 8 then raise exception 'Ingresá un teléfono válido'; end if;
  if rodar.t(p_b, 'origen_dir') is null or p_b ->> 'origen_lat' is null then raise exception 'Indicá el origen en el mapa o buscá la dirección'; end if;
  if rodar.t(p_b, 'token') is not null then
    select u.* into s from rodar.sesiones x join rodar.usuarios u on u.id = x.usuario_id where x.token = p_b ->> 'token' and x.activa;
    if s.corporativo_id is not null then corp := s.corporativo_id; medio := 'cuenta_corriente'; end if;
  end if;
  ids := rodar.crear_viaje(p_b || jsonb_build_object('telefono', tel, 'alias', p_b ->> 'nombre', 'canal', 'web', 'medio_pago', medio, 'corporativo_id', corp, 'pin_requerido', true,
    'cantidad_moviles', 1, 'estado', 'pendiente', 'movil_id', null, 'conductor_id', null, 'programado', null, 'monto_fijo', null), null);
  perform rodar.procesar();
  return jsonb_build_object('id', ids[1], 'k', rodar.firma(ids[1]), 'canal', rodar.topico('viaje-' || ids[1] || '-' || rodar.firma(ids[1])));
end $$;
create or replace function public.r_pub_seguimiento(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare vid bigint := (p_q ->> 'id')::bigint;
begin
  if p_q ->> 'k' is distinct from rodar.firma(vid) then raise exception 'Enlace inválido'; end if;
  perform rodar.procesar();
  return rodar.publico_pasajero(vid) || jsonb_build_object('canal', rodar.topico('viaje-' || vid || '-' || rodar.firma(vid)));
end $$;
create or replace function public.r_pub_cancelar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare vid bigint := (p_q ->> 'id')::bigint; nada rodar.usuarios;
begin
  if p_q ->> 'k' is distinct from rodar.firma(vid) then raise exception 'Enlace inválido'; end if;
  perform rodar.anular(vid, nada, 'Cancelado por el pasajero');
  return '{"ok":true}';
end $$;
create or replace function public.r_pub_calificar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare vid bigint := (p_q ->> 'id')::bigint;
begin
  if p_q ->> 'k' is distinct from rodar.firma(vid) then raise exception 'Enlace inválido'; end if;
  update rodar.viajes set calificacion = greatest(1, least(5, coalesce(rodar.n(p_b, 'estrellas'), 5)::int)) where id = vid and estado = 'finalizado';
  return '{"ok":true}';
end $$;
create or replace function public.r_pub_soporte(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare cid bigint; tel text := rodar.t(p_b, 'telefono');
begin
  if tel is null or rodar.t(p_b, 'texto') is null then raise exception 'Completá teléfono y mensaje'; end if;
  select id into cid from rodar.soporte_conv where tipo = 'cliente' and cliente_tel = tel and not cerrada;
  if cid is null then insert into rodar.soporte_conv(tipo, cliente_tel, cliente_alias, asunto, actualizado) values ('cliente', tel, rodar.t(p_b, 'alias'), 'Consulta app pasajero', rodar.ahora()) returning id into cid; end if;
  insert into rodar.soporte_msg(conv_id, de, texto, fecha) values (cid, 'cliente', p_b ->> 'texto', rodar.ahora());
  update rodar.soporte_conv set no_leidos = no_leidos + 1, actualizado = rodar.ahora() where id = cid;
  perform rodar.emit('panel', 'soporte', jsonb_build_object('conv', cid));
  return '{"ok":true}';
end $$;


-- ======== 09_sim_seed.sql ========
-- ===================== Simulador (modo demo) =====================
create table if not exists rodar.sim_estado (
  movil_id bigint primary key, obj_lat float8, obj_lng float8, espera float8 default 0, metros float8 default 0,
  decide_at timestamptz, hacia_parada bigint, dlat float8, dlng float8
);

create or replace function rodar.azar(a float8, b float8) returns float8 language sql volatile as $$ select a + random() * (b - a) $$;
create or replace function rodar.calle_azar() returns text language sql volatile as $$
  select (array['San Martín','Belgrano','Urquiza','Mitre','Sarmiento','Rivadavia','25 de Mayo','Moreno','Alberdi','Pellegrini','Italia','España','Entre Ríos','Corrientes','Güemes','Las Heras','Laprida','Colón','Brown','Pringles'])[1 + floor(random() * 20)::int]
    || ' ' || (50 + floor(random() * 1850))::int $$;

-- avanza (lat,lng) hacia (dlat,dlng) 'metros'; devuelve [lat, lng, llegó]
create or replace function rodar.avanzar(lat float8, lng float8, dlat float8, dlng float8, metros float8) returns float8[] language plpgsql immutable as $$
#variable_conflict use_variable

declare d float8 := rodar.dist(lat, lng, dlat, dlng); f float8;
begin
  if d is null or d <= metros then return array[dlat, dlng, 1]; end if;
  f := metros / d;
  return array[lat + (dlat - lat) * f, lng + (dlng - lng) * f, 0];
end $$;

create or replace function rodar.sim_tick() returns void language plpgsql as $$
#variable_conflict use_variable

declare conf jsonb := rodar.cfg('simulador', '{"flota":true,"demanda":true}'); e jsonb := rodar.cfg('empresa', '{}'); clat float8 := (e ->> 'lat')::float8; clng float8 := (e ->> 'lng')::float8;
  ult timestamptz := (rodar.cfg('sim_ultimo') #>> '{}')::timestamptz; dt float8; m rodar.moviles; st rodar.sim_estado; v rodar.viajes; r float8[]; paso float8; z rodar.zonas; ids bigint[]; cli record; n int;
begin
  if not coalesce((conf ->> 'flota')::boolean, false) and not coalesce((conf ->> 'demanda')::boolean, false) then return; end if;
  if ult is not null and now() - ult < interval '1800 milliseconds' then return; end if;
  if not pg_try_advisory_xact_lock(434343) then return; end if;
  perform rodar.cfg_set('sim_ultimo', to_jsonb(now()));
  dt := least(10, greatest(1, coalesce(extract(epoch from now() - ult), 2)));

  if coalesce((conf ->> 'flota')::boolean, false) then
    -- arranque: conecta hasta 9 móviles simulados
    select count(*) into n from rodar.moviles where simulado and estado <> 'desconectado';
    if n = 0 then
      update rodar.moviles x set conductor_id = (select usuario_id from rodar.movil_conductores where movil_id = x.id order by usuario_id limit 1), estado = 'disponible'
        where x.id in (select id from rodar.moviles where simulado and habilitado and estado = 'desconectado' order by numero limit 9);
    end if;
    for m in select * from rodar.moviles where simulado and estado not in ('desconectado', 'fuera_servicio') loop
      select * into st from rodar.sim_estado where movil_id = m.id;
      if not found then
        insert into rodar.sim_estado(movil_id, obj_lat, obj_lng) values (m.id, clat + rodar.azar(-0.014, 0.014), clng + rodar.azar(-0.017, 0.017)) returning * into st;
      end if;
      if m.lat is null then update rodar.moviles set lat = clat + rodar.azar(-0.01, 0.01), lng = clng + rodar.azar(-0.01, 0.01) where id = m.id returning * into m; end if;
      select * into v from rodar.viajes where movil_id = m.id and estado in ('ofrecido', 'confirmado', 'en_curso') order by id desc limit 1;
      paso := 22 * dt;
      if v.id is not null and v.estado = 'ofrecido' then
        if st.decide_at is null then update rodar.sim_estado set decide_at = now() + make_interval(secs => rodar.azar(2.5, 7)) where movil_id = m.id;
        elsif now() > st.decide_at then
          update rodar.sim_estado set decide_at = null where movil_id = m.id;
          begin if random() < 0.9 then perform rodar.aceptar(v.id, m.id); else perform rodar.rechazar(v.id, m.id); end if; exception when others then null; end;
        end if;
        continue;
      elsif v.id is not null and v.estado = 'confirmado' then
        r := rodar.avanzar(m.lat, m.lng, coalesce(v.origen_lat, m.lat), coalesce(v.origen_lng, m.lng), paso);
        if r[3] = 0 then perform rodar.posicion(m.id, r[1], r[2], paso / dt * 3.6, null, true);
        else
          if v.llegada_at is null then perform rodar.llegada(v.id); end if;
          update rodar.sim_estado set espera = espera + dt where movil_id = m.id returning * into st;
          if st.espera > 12 then
            update rodar.sim_estado set espera = 0, metros = 0, dlat = coalesce(v.destino_lat, clat + rodar.azar(-0.014, 0.014)), dlng = coalesce(v.destino_lng, clng + rodar.azar(-0.017, 0.017)) where movil_id = m.id;
            begin perform rodar.iniciar(v.id, v.pin); exception when others then null; end;
          end if;
        end if;
      elsif v.id is not null and v.estado = 'en_curso' then
        if st.dlat is null then update rodar.sim_estado set dlat = coalesce(v.destino_lat, clat + rodar.azar(-0.014, 0.014)), dlng = coalesce(v.destino_lng, clng + rodar.azar(-0.017, 0.017)) where movil_id = m.id returning * into st; end if;
        r := rodar.avanzar(m.lat, m.lng, st.dlat, st.dlng, paso);
        update rodar.sim_estado set metros = metros + coalesce(rodar.dist(m.lat, m.lng, r[1], r[2]), 0) where movil_id = m.id returning * into st;
        perform rodar.posicion(m.id, r[1], r[2], paso / dt * 3.6, null, true);
        if r[3] = 1 then
          begin perform rodar.finalizar(v.id, (st.metros * 1.15)::numeric, rodar.azar(0, 150)::numeric, null, r[1], r[2], coalesce(v.destino_dir, rodar.calle_azar())); exception when others then null; end;
          update rodar.sim_estado set dlat = null, dlng = null, metros = 0, obj_lat = clat + rodar.azar(-0.014, 0.014), obj_lng = clng + rodar.azar(-0.017, 0.017) where movil_id = m.id;
        end if;
      elsif m.estado = 'en_parada' then
        if random() < 0.004 * dt then perform rodar.set_estado_movil(m.id, 'disponible'); end if;
        perform rodar.posicion(m.id, m.lat, m.lng, 0, null, true);
      elsif m.estado = 'disponible' then
        if st.hacia_parada is null and random() < 0.01 * dt then
          select * into z from rodar.zonas where es_parada and parada_lat is not null order by random() limit 1;
          if z.id is not null then update rodar.sim_estado set hacia_parada = z.id, obj_lat = z.parada_lat + rodar.azar(-0.0003, 0.0003), obj_lng = z.parada_lng + rodar.azar(-0.0003, 0.0003) where movil_id = m.id returning * into st; end if;
        end if;
        r := rodar.avanzar(m.lat, m.lng, st.obj_lat, st.obj_lng, paso * 0.6);
        perform rodar.posicion(m.id, r[1], r[2], paso * 0.6 / dt * 3.6, null, true);
        if r[3] = 1 then
          if st.hacia_parada is not null then begin perform rodar.set_estado_movil(m.id, 'en_parada', st.hacia_parada); exception when others then null; end; end if;
          update rodar.sim_estado set hacia_parada = null, obj_lat = clat + rodar.azar(-0.014, 0.014), obj_lng = clng + rodar.azar(-0.017, 0.017) where movil_id = m.id;
        end if;
        if random() < 0.0015 * dt then
          begin
            ids := rodar.crear_viaje(jsonb_build_object('origen_dir', rodar.calle_azar(), 'origen_lat', r[1], 'origen_lng', r[2], 'canal', 'movil', 'origen_tipo', 'calle', 'alias', 'CALLE', 'movil_id', m.id, 'conductor_id', m.conductor_id, 'pin_requerido', false), null);
            perform rodar.aceptar(ids[1], m.id);
          exception when others then null; end;
        end if;
      end if;
    end loop;
  end if;

  if coalesce((conf ->> 'demanda')::boolean, false) and random() < 0.035 * dt then
    select c.telefono, c.alias, d.direccion, d.lat, d.lng into cli from rodar.clientes c join rodar.cliente_domicilios d on d.cliente_id = c.id where not c.bloqueado and c.baja_at is null order by random() limit 1;
    if found then
      begin
        perform rodar.crear_viaje(jsonb_build_object('telefono', cli.telefono, 'alias', cli.alias, 'origen_dir', cli.direccion, 'origen_loc', e ->> 'localidad', 'origen_prov', e ->> 'provincia', 'origen_lat', cli.lat, 'origen_lng', cli.lng,
          'destino_dir', case when random() < 0.5 then rodar.calle_azar() end, 'destino_lat', case when random() < 0.5 then clat + rodar.azar(-0.014, 0.014) end, 'destino_lng', clng + rodar.azar(-0.017, 0.017),
          'canal', (array['centralita','centralita','whatsapp','aplicacion','web','telegram'])[1 + floor(random() * 6)::int], 'medio_pago', case when random() < 0.15 then 'mercadopago' else 'efectivo' end), null);
      exception when others then null; end;
    end if;
  end if;
end $$;

-- el destino sin lat no tiene que tener lng: limpieza
create or replace function rodar.ciclo_cron() returns void language plpgsql as $$
#variable_conflict use_variable

begin perform rodar.procesar(); perform rodar.ciclo_lento(); perform rodar.sim_tick(); end $$;

-- sobreescribe r_tick / r_estado para incluir el simulador
create or replace function public.r_tick(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

begin perform rodar.usuario(p_token); perform rodar.ciclo_cron(); return '{"ok":true}'; end $$;

-- ===================== Datos de ejemplo (solo si la base está vacía) =====================
create or replace function rodar.seed() returns void language plpgsql as $$
#variable_conflict use_variable

declare clat float8 := -30.9545; clng float8 := -58.7835; nombres text[] := array['Lucas','Martín','Sofía','Valentina','Joaquín','Camila','Federico','Rocío','Nicolás','Agustina','Tomás','Julieta','Gonzalo','Paula','Ramiro','Lorena','Hernán','Mariela','Sergio','Daniela'];
  apellidos text[] := array['Benítez','Romero','Acosta','Medina','Herrera','Ruiz','Sosa','Ferreyra','Godoy','Ríos','Vera','Ojeda','Molina','Correa','Paz','Luna','Aguirre','Ledesma','Cabrera','Ponce'];
  tit bigint[] := '{}'; cond bigint[] := '{}'; nid bigint; i int; d int; k int; cant int; mv rodar.moviles; t0 timestamp; ta timestamp; ti timestamp; tf timestamp; cli record; metros float8; anul boolean; calle boolean;
  dlat float8; dlng float8; t rodar.tarifas; monto numeric; mins float8; dia date; cnd bigint; lat float8; lng float8; est text; tt timestamp; objlat float8; objlng float8; r float8[]; sal numeric; vid bigint;
begin
  if exists(select 1 from rodar.usuarios) then return; end if;
  perform rodar.cfg_set('secreto', to_jsonb(encode(extensions.gen_random_bytes(16), 'hex')));
  perform rodar.cfg_set('webhook_token', to_jsonb(encode(extensions.gen_random_bytes(12), 'hex')));
  perform rodar.cfg_set('empresa', jsonb_build_object('nombre', 'Remises TOQUE!', 'razon_social', 'Remises Demo S.R.L.', 'cuit', '30-00000000-0', 'direccion', 'San Martín 100', 'localidad', 'Federal',
    'provincia', 'Entre Ríos', 'telefono', '3454 000000', 'email', 'central@demo.local', 'lat', clat, 'lng', clng, 'tipo_servicio', 'Remis', 'quien_factura', 'La empresa', 'firmante', 'Titular',
    'firmante_nombre', 'Responsable Demo', 'apps_ios', true, 'pagos_electronicos', true, 'boton_emergencia', true, 'descripcion', 'Servicio de remis con despacho centralizado y seguimiento en tiempo real.'));
  perform rodar.cfg_set('mp', '{"absorbe":"central","tasas":{"inmediata":6.29,"d10":4.39,"d18":3.39,"d35":1.79},"plazo":"inmediata","link_pago":"","alias_cobro":""}');
  perform rodar.cfg_set('dispatch', '{"timeout_oferta_seg":20,"radio_busqueda_m":6000,"max_intentos":5,"deuda_bloqueo":-5000}');
  perform rodar.cfg_set('simulador', '{"flota":true,"demanda":true}');

  insert into rodar.usuarios(documento, usuario, nombre, apellido, email, telefono, password_hash, roles) values
    ('1000', 'admin', 'Admin', 'Central', 'admin@demo.local', '3454000001', rodar.hash('admin123'), 'admin,operador,gestion'),
    ('1001', 'operador', 'Laura', 'Operadora', 'operador@demo.local', '3454000002', rodar.hash('operador123'), 'operador'),
    ('1002', 'contable', 'Carlos', 'Contable', 'contable@demo.local', '3454000003', rodar.hash('contable123'), 'gestion');
  for i in 0 .. 3 loop
    insert into rodar.usuarios(documento, usuario, nombre, apellido, telefono, password_hash, roles) values ((20000000 + i * 1111)::text, 'titular' || (i + 1), nombres[i + 1], apellidos[i + 1], '345450' || (1000 + i),
      rodar.hash('titular123'), case when i = 0 then 'titular,conductor' else 'titular' end) returning id into nid;
    tit := tit || nid;
  end loop;
  cond := array[tit[1]];
  for i in 0 .. 13 loop
    insert into rodar.usuarios(documento, usuario, nombre, apellido, telefono, password_hash, roles) values ((30000000 + i * 1373)::text, 'conductor' || (i + 1), nombres[(i + 4) % 20 + 1], apellidos[(i + 6) % 20 + 1],
      '345460' || (1000 + i), rodar.hash('conductor123'), 'conductor') returning id into nid;
    cond := cond || nid;
  end loop;
  insert into rodar.corporativos(nombre, cuit, centro_costo, contacto, telefono) values ('Cooperativa Agrícola Demo', '30-11111111-1', 'Administración', 'Mesa de entradas', '3454111111');
  insert into rodar.usuarios(documento, usuario, nombre, apellido, email, telefono, password_hash, roles, corporativo_id) values ('40000000', 'empresa', 'Usuario', 'Corporativo', 'corp@demo.local', '3454111112', rodar.hash('empresa123'), 'corporativo', 1);

  insert into rodar.planes(descripcion, modo_pago, modo_cobro, monto_fijo, periodicidad, sistema) values ('Sin abono', 'prepago', 'fijo', 0, 'mensual', true);
  insert into rodar.planes(descripcion, modo_pago, modo_cobro, tipo1, vencer_saldo, monto_fijo, monto_viaje, periodicidad, dia_mes, minimo) values ('Abono mensual + viaje', 'prepago', 'fijo_viaje', true, true, 27000, 1350, 'mensual', 1, 5000);
  insert into rodar.planes(descripcion, modo_pago, modo_cobro, monto_fijo, periodicidad, dia_semana) values ('Semanal fijo', 'pospago', 'fijo', 9000, 'semanal', 1);
  insert into rodar.planes(descripcion, modo_pago, modo_cobro, pct_viaje, periodicidad, minimo) values ('Porcentaje por viaje 10%', 'prepago', 'porcentaje', 10, 'mensual', 3000);

  insert into rodar.zonas(nombre, poligono, color, parada_lat, parada_lng, orden) values
    ('Centro', '[[-30.960,-58.792],[-30.960,-58.775],[-30.949,-58.775],[-30.949,-58.792]]', '#1f8a8a', -30.9545, -58.7835, 1),
    ('Norte', '[[-30.949,-58.800],[-30.949,-58.765],[-30.935,-58.765],[-30.935,-58.800]]', '#2f6fd6', -30.943, -58.782, 2),
    ('Sur', '[[-30.975,-58.800],[-30.975,-58.765],[-30.960,-58.765],[-30.960,-58.800]]', '#d6782f', -30.967, -58.783, 3),
    ('Este', '[[-30.960,-58.775],[-30.960,-58.758],[-30.949,-58.758],[-30.949,-58.775]]', '#8a2fd6', -30.9545, -58.767, 4),
    ('Oeste', '[[-30.960,-58.810],[-30.960,-58.792],[-30.949,-58.792],[-30.949,-58.810]]', '#2fa04a', -30.9545, -58.801, 5),
    ('Terminal', '[[-30.9515,-58.7800],[-30.9515,-58.7760],[-30.9490,-58.7760],[-30.9490,-58.7800]]', '#c0392b', -30.9502, -58.778, 6);
  insert into rodar.zonas_peligrosas(nombre, poligono, creado) values ('Descampado sur (ejemplo)', '[[-30.978,-58.790],[-30.978,-58.780],[-30.974,-58.780],[-30.974,-58.790]]', rodar.ahora());

  for i in 1 .. 12 loop
    insert into rodar.moviles(numero, patente, licencia, marca, modelo, anio, color, titular_id, plan_id, estado, lat, lng, simulado)
    values (i, 'A' || chr(65 + i) || lpad((100 + i * 7)::text, 3, '0') || 'X' || chr(70 + i % 10), 'L-' || (500 + i),
      (array['Chevrolet','Fiat','Toyota','Renault','Volkswagen','Peugeot'])[i % 6 + 1], (array['Prisma','Cronos','Etios','Logan','Voyage','208'])[i % 6 + 1], 2015 + i % 9,
      (array['Blanco','Gris','Negro','Rojo'])[i % 4 + 1], tit[i % 4 + 1], case when i % 3 = 0 then 3 else 2 end, 'desconectado', clat + rodar.azar(-0.01, 0.01), clng + rodar.azar(-0.012, 0.012), true)
    returning id into nid;
    insert into rodar.movil_conductores values (nid, cond[(i - 1) % array_length(cond, 1) + 1]);
    if i % 4 = 0 then insert into rodar.movil_conductores values (nid, cond[(i + 5) % array_length(cond, 1) + 1]) on conflict do nothing; end if;
  end loop;

  insert into rodar.tarifas(orden, nombre, tipo, bajada, con_espera, espera_seg, precio_ficha, cortesia_mts, cortesia_min, dias, hora_desde, hora_hasta) values (1, 'Diurna', 'fija', 2800, true, 60, 140, 0, 2, '[1,2,3,4,5,6]', '06:00', '21:59');
  insert into rodar.tarifas(orden, nombre, tipo, bajada, con_espera, espera_seg, precio_ficha, cortesia_min, dias, feriado, hora_desde, hora_hasta, suba_max) values (2, 'Nocturna / domingos', 'dinamica', 3300, true, 60, 165, 2, '[0,1,2,3,4,5,6]', true, '22:00', '05:59', 25);
  insert into rodar.tarifas(orden, nombre, tipo, bajada, con_espera, espera_seg, precio_ficha, dias, hora_desde, hora_hasta) values (3, 'Domingo y feriado', 'fija', 3300, true, 60, 165, '[0]', '06:00', '21:59');

  insert into rodar.canales(codigo, nombre, orden, exigir_pin) values ('whatsapp','WhatsApp',0,false),('instagram','Instagram',1,false),('facebook','Facebook',2,false),('telegram','Telegram',3,false),
    ('aplicacion','Aplicación pasajero',4,true),('web','Pedido web',5,false),('operador','Operador',6,false),('movil','Móvil (calle)',7,false),('centralita','Centralita telefónica',8,false);
  insert into rodar.medios_pago(codigo, nombre, orden, habilitado) values ('efectivo','Efectivo',0,true),('mercadopago','Mercado Pago',1,true),('transferencia','Transferencia',2,true),
    ('cuenta_corriente','Cuenta corriente (corporativo)',3,true),('tarjeta','Tarjeta (posnet del móvil)',4,false),('vale','Vale / voucher',5,false);
  insert into rodar.feriados(fecha, descripcion) values ('2026-01-01','Año Nuevo'),('2026-02-16','Carnaval'),('2026-02-17','Carnaval'),('2026-03-24','Día de la Memoria'),('2026-04-02','Malvinas'),
    ('2026-04-03','Viernes Santo'),('2026-05-01','Día del Trabajador'),('2026-05-25','Revolución de Mayo'),('2026-06-17','Paso a la Inmortalidad de Güemes'),('2026-06-20','Día de la Bandera'),
    ('2026-07-09','Independencia'),('2026-08-17','Paso a la Inmortalidad de San Martín'),('2026-10-12','Diversidad Cultural'),('2026-11-23','Soberanía Nacional'),('2026-12-08','Inmaculada Concepción'),('2026-12-25','Navidad');
  insert into rodar.modulos(codigo, nombre, descripcion, precio, unidad, obligatorio, activo_prox) values
    ('flota','Pack móviles','Gestión de flota, app de conductores y despacho.',1500,'móvil',true,true),('corporativo','Clientes corporativos','Empresas, centros de costo, viajes y facturación corporativa.',15000,'mes',false,true),
    ('operadores','Pantalla para operadores','Mapa en tiempo real, radio, telefonía, anulación e informes.',20000,'mes',false,true),('chat','Chat multicanal','WhatsApp / Telegram / web en una sola bandeja.',12000,'mes',false,true),
    ('telefonia','Puestos de telefonía','Puestos con identificador de llamadas.',8000,'puesto',false,true),('app_pasajero','App pasajero con marca propia','Publicación de la app de pasajeros con tu marca.',25000,'mes',false,true);
  insert into rodar.novedades(seccion, etiqueta, titulo, cuerpo, fecha, alerta) values
    ('destacado','NUEVO','App de conductores web','Los conductores ingresan desde conductor.html con su usuario o DNI. Incluye PIN de abordaje, viaje de calle, paradas, radio PTT y ticket del viaje.', rodar.hoy() - 4, null),
    ('destacado','NUEVO','Pedido web de pasajeros','Compartí el enlace pasajero.html: el pasajero pide el viaje, ve el móvil asignado y el PIN de seguridad.', rodar.hoy() - 8, null),
    ('destacado','AVISO','Aviso de viaje por WhatsApp','Desde el mapa, en cada viaje, podés copiar un mensaje de "móvil asignado" con el link de seguimiento.', rodar.hoy() - 13, 'Evitá enviar muchos mensajes idénticos seguidos: personalizá el texto.'),
    ('semana','MEJORA','Tarifa dinámica con techo','El índice sube de a 5% según demanda, móviles libres y clima, sin pasar la suba máxima configurada.', rodar.hoy() - 5, null),
    ('semana','MEJORA','Recorrido histórico con reproducción','Reproducí el recorrido de un móvil con velocidades 0.5x a 4x y exportalo en CSV.', rodar.hoy() - 6, null),
    ('archivo','GUÍA','Cómo cargar un feriado','Administración → Días feriados → Nuevo.', rodar.hoy() - 70, null);

  for i in 0 .. 119 loop
    insert into rodar.clientes(telefono, alias, creado) values ('3454' || (400000 + i * 37), case when i % 7 = 0 then 'EVENTUAL' else nombres[1 + floor(random() * 20)::int] || ' ' || apellidos[1 + floor(random() * 20)::int] end, rodar.ahora()) returning id into nid;
    insert into rodar.cliente_domicilios(cliente_id, direccion, localidad, provincia, lat, lng, ultimo_uso) values (nid, rodar.calle_azar(), 'Federal', 'Entre Ríos', clat + rodar.azar(-0.017, 0.017), clng + rodar.azar(-0.02, 0.02), rodar.ahora());
  end loop;
  update rodar.clientes set bloqueado = true, motivo_bloqueo = 'No se presentó 3 veces', bloqueado_por = 1, bloqueado_at = rodar.ahora() - interval '3 days' where id in (5, 17);

  select * into t from rodar.tarifas where id = 1;
  for d in reverse 45 .. 0 loop
    dia := rodar.hoy() - d;
    cant := floor(rodar.azar(18, 40));
    insert into rodar.conexion_diaria(usuario_id, fecha, segundos, cargados, tipo) values (2, dia, floor(rodar.azar(6, 8) * 3600), floor(cant * 0.6), 'web'), (1, dia, floor(rodar.azar(2, 5) * 3600), floor(cant * 0.3), 'web') on conflict do nothing;
    insert into rodar.conexion_diaria(usuario_id, fecha, segundos, tipo) select distinct usuario_id, dia, floor(rodar.azar(3, 10) * 3600), 'app' from rodar.movil_conductores where random() < 0.8 on conflict do nothing;
    for k in 1 .. cant loop
      if d = 0 and k > 6 then exit; end if;
      t0 := dia + make_interval(hours => floor(rodar.azar(6, 24))::int, mins => floor(rodar.azar(0, 60))::int);
      if t0 > rodar.ahora() then continue; end if;
      select c.id, c.telefono, d2.direccion, d2.lat, d2.lng into cli from rodar.clientes c join rodar.cliente_domicilios d2 on d2.cliente_id = c.id order by random() limit 1;
      select * into mv from rodar.moviles order by random() limit 1;
      select usuario_id into cnd from rodar.movil_conductores where movil_id = mv.id limit 1;
      calle := random() < 0.15; anul := random() < 0.06;
      dlat := clat + rodar.azar(-0.017, 0.017); dlng := clng + rodar.azar(-0.02, 0.02);
      metros := rodar.dist(cli.lat, cli.lng, dlat, dlng) * 1.3;
      ta := t0 + make_interval(secs => rodar.azar(20, 120)); ti := ta + make_interval(mins => rodar.azar(3, 9)::int);
      mins := metros / 1000 / 28 * 60 + rodar.azar(1, 4); tf := ti + make_interval(secs => mins * 60);
      monto := rodar.calcular_monto(t, metros::numeric, rodar.azar(0, 200)::numeric, 1);
      insert into rodar.viajes(cliente_id, telefono, alias, origen_dir, origen_loc, origen_prov, origen_lat, origen_lng, destino_dir, destino_lat, destino_lng, canal, origen_tipo, estado,
        movil_id, conductor_id, operador_id, zona_id, creado, asignado_at, inicio_at, fin_at, monto, km, minutos, medio_pago, calificacion, anulado_at, motivo_anulacion, pin)
      values (case when calle then null else cli.id end, case when calle then null else cli.telefono end, case when calle then 'CALLE' end, cli.direccion, 'Federal', 'Entre Ríos', cli.lat, cli.lng,
        rodar.calle_azar(), dlat, dlng, case when calle then 'movil' else (array['centralita','centralita','centralita','whatsapp','whatsapp','aplicacion','web','operador','telegram'])[1 + floor(random() * 9)::int] end,
        case when calle then 'calle' else 'central' end, case when anul then 'anulado' else 'finalizado' end, mv.id, cnd, case when calle then null else (array[1, 2, 2])[1 + floor(random() * 3)::int] end,
        (rodar.zona_de(cli.lat, cli.lng)).id, t0, ta, case when anul then null else ti end, case when anul then null else tf end, case when anul then null else monto end,
        case when anul then null else round((metros / 1000)::numeric, 2) end, case when anul then null else round(mins::numeric, 1) end,
        case when random() < 0.12 then 'mercadopago' else 'efectivo' end, case when not anul and random() < 0.5 then floor(rodar.azar(3, 6))::int end,
        case when anul then ta end, case when anul then (array['Cliente canceló','No se presentó','Duplicado'])[1 + floor(random() * 3)::int] end, (1000 + floor(random() * 9000))::int::text)
      returning id into vid;
      if not anul then
        insert into rodar.eventos_moviles(fecha, movil_id, movil_numero, tipo, ref, detalle) values (t0, mv.id, mv.numero, 'ofrecido', '#' || vid, 'Viaje ofrecido'), (ta, mv.id, mv.numero, 'aceptado', '#' || vid, 'Viaje aceptado');
        if mv.plan_id = 2 then insert into rodar.cuenta_movimientos(movil_id, fecha, tipo, monto, detalle, viaje_id) values (mv.id, tf, 'viaje', -1350, 'Viaje #' || vid, vid); end if;
        if (select medio_pago from rodar.viajes where id = vid) = 'mercadopago' then
          insert into rodar.mp_pagos(tipo, movil_id, viaje_id, monto, comision, estado, acreditado, medio, liberacion, mp_id, fecha, rendido)
          values ('viaje', mv.id, vid, monto, round(monto * 0.0339, 2), 'pagado', true, (array['account_money','credit_card','debit_card'])[1 + floor(random() * 3)::int], (tf + interval '18 days')::date, (9000000000 + vid)::text, tf, d > 20);
        end if;
      end if;
    end loop;
    if extract(day from dia) = 1 then
      insert into rodar.cuenta_movimientos(movil_id, fecha, tipo, monto, detalle)
        select id, dia, 'cuota', -27000, 'Cuota mensual' from rodar.moviles where plan_id = 2 union all
        select id, dia + interval '10 hours', 'pago', 27000, 'Pago en efectivo' from rodar.moviles where plan_id = 2 union all
        select id, dia + interval '10 hours 1 second', 'saldo_viajes', 27000, 'Saldo para viajes (tipo 1)' from rodar.moviles where plan_id = 2 union all
        select id, dia, 'cuota', -36000, 'Cuotas semanales' from rodar.moviles where plan_id = 3 union all
        select id, dia + interval '12 hours', 'pago', 36000, 'Pago transferencia' from rodar.moviles where plan_id = 3;
    end if;
  end loop;
  for mv in select * from rodar.moviles loop
    sal := rodar.saldo(mv.id); monto := round(rodar.azar(2000, 30000)::numeric, -2);
    if sal < monto then insert into rodar.cuenta_movimientos(movil_id, fecha, tipo, monto, detalle) values (mv.id, rodar.ahora() - interval '1 day', 'pago', monto - sal, 'Pagos acumulados (datos de ejemplo)'); end if;
  end loop;
  insert into rodar.cuenta_movimientos(movil_id, fecha, tipo, monto, detalle) values (7, rodar.ahora(), 'ajuste', -60000, 'Deuda de ejemplo');
  insert into rodar.penalizaciones(movil_id, hasta, usuario_id, motivo, creado) values (11, rodar.ahora() + interval '2 hours', 1, 'Rechazó 3 viajes seguidos', rodar.ahora());
  insert into rodar.negativos(cliente_id, movil_id, usuario_id, creado) values (3, 2, 1, rodar.ahora());
  insert into rodar.solicitudes_conductor(nombre, apellido, dni, telefono, email, patente, marca, modelo, anio, origen, docs, fecha) values ('Esteban', 'Quiroga', '35123456', '3454999000', 'esteban@ejemplo.local', 'AE123ZZ', 'Fiat', 'Cronos', 2021, 'web', '[{"tipo":"Licencia","archivo":null},{"tipo":"Seguro","archivo":null}]', rodar.ahora());
  insert into rodar.soporte_conv(tipo, movil_id, asunto, no_leidos, actualizado) values ('movil', 3, 'Consulta app conductor', 1, rodar.ahora()) returning id into nid;
  insert into rodar.soporte_msg(conv_id, de, texto, fecha) values (nid, 'movil', 'Hola, no me aparece la parada Terminal en el menú.', rodar.ahora());
  insert into rodar.soporte_conv(tipo, cliente_tel, cliente_alias, asunto, no_leidos, actualizado) values ('cliente', '3454400037', 'Pasajero demo', 'Consulta app pasajero', 1, rodar.ahora()) returning id into nid;
  insert into rodar.soporte_msg(conv_id, de, texto, fecha) values (nid, 'cliente', 'Me cobraron de más el viaje de ayer, ¿pueden revisar?', rodar.ahora());
  insert into rodar.chat_conv(canal, telefono, alias, no_leidos, actualizado) values ('whatsapp', '3454400074', 'Marta', 1, rodar.ahora()) returning id into nid;
  insert into rodar.chat_msg(conv_id, de, texto, fecha) values (nid, 'cliente', 'Hola! necesito un remis a Belgrano 845 por favor', rodar.ahora());
  insert into rodar.autoridades(nombre, cargo, organismo, direccion, email) values ('[Plantilla] Director/a de Tránsito', 'Director/a', 'Dirección de Tránsito Municipal', 'Palacio Municipal', 'transito@municipio.local');
  insert into rodar.acciones_usuarios(fecha, actor_id, actor, tipo, afectado, detalle) values (rodar.ahora(), 1, 'Admin Central', 'cliente_bloqueo', '3454400185', 'No se presentó 3 veces');
  -- recorridos de las últimas 6 horas para 6 móviles
  for mv in select * from rodar.moviles where numero <= 6 loop
    lat := mv.lat; lng := mv.lng; tt := rodar.ahora() - interval '6 hours'; est := 'disponible';
    objlat := clat + rodar.azar(-0.015, 0.015); objlng := clng + rodar.azar(-0.018, 0.018);
    while tt < rodar.ahora() loop
      r := rodar.avanzar(lat, lng, objlat, objlng, 120); lat := r[1]; lng := r[2];
      if r[3] = 1 then objlat := clat + rodar.azar(-0.015, 0.015); objlng := clng + rodar.azar(-0.018, 0.018); est := (array['disponible','con_pasajero','confirmado','en_parada'])[1 + floor(random() * 4)::int]; end if;
      insert into rodar.posiciones(movil_id, ts, lat, lng, estado, velocidad) values (mv.id, tt, lat, lng, est, case when est = 'en_parada' then 0 else rodar.azar(15, 45) end);
      tt := tt + interval '15 seconds';
    end loop;
  end loop;
end $$;

select rodar.seed();

-- ===================== Permisos =====================
do $$ begin
  if exists(select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on schema rodar from anon, authenticated';
    execute 'revoke all on all tables in schema rodar from anon, authenticated';
    execute 'revoke execute on all functions in schema rodar from public, anon, authenticated';
  end if;
end $$;
revoke execute on all functions in schema rodar from public;

-- Tiempo máximo por consulta para la API (Supabase trae 3 s para anon; los informes grandes pueden necesitar más)
do $$ begin
  if exists(select 1 from pg_roles where rolname = 'anon') then execute 'alter role anon set statement_timeout = ''20s'''; end if;
exception when others then raise notice 'No se pudo ajustar statement_timeout: %', sqlerrm; end $$;
notify pgrst, 'reload schema';

-- ===================== Ciclo automático con pg_cron (opcional pero recomendado) =====================
do $$ begin
  begin
    create extension if not exists pg_cron with schema pg_catalog;
  exception when others then raise notice 'pg_cron no está disponible: activalo en Database → Extensions (o Integrations → Cron) y volvé a correr este bloque.'; end;
  if exists(select 1 from pg_extension where extname = 'pg_cron') then
    begin perform cron.unschedule('rodar-ciclo'); exception when others then null; end;
    perform cron.schedule('rodar-ciclo', '5 seconds', 'select rodar.ciclo_cron()');
  end if;
exception when others then raise notice 'No se pudo programar el ciclo con pg_cron: %. El sistema igual funciona mientras haya un panel o una app abierta.', sqlerrm;
end $$;


-- ======== 10_tarifa_tabla.sql ========
-- Tarifa por tabla (precio por kilómetro recorrido y por minutos de espera), en lugar de bajada + fichas.
alter table rodar.tarifas add column if not exists tabla jsonb;

create or replace function rodar.precio_tabla_km(tabla jsonb, metros numeric) returns numeric language plpgsql immutable set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u int := floor(greatest(0, coalesce(metros, 0)) / 100); p numeric; lu int; lp numeric;
cada int := greatest(1, coalesce((tabla -> 'extra' ->> 'cada_m')::int, 400) / 100); monto numeric := coalesce((tabla -> 'extra' ->> 'monto')::numeric, 0);
begin
if jsonb_array_length(coalesce(tabla -> 'km', '[]')) = 0 then return 0; end if;
select round((e ->> 0)::numeric * 10)::int, (e ->> 1)::numeric into lu, lp from jsonb_array_elements(tabla -> 'km') e order by (e ->> 0)::numeric desc limit 1;
if u > lu then return lp + ceil((u - lu)::numeric / cada) * monto; end if;
select (e ->> 1)::numeric into p from jsonb_array_elements(tabla -> 'km') e where round((e ->> 0)::numeric * 10) <= u order by (e ->> 0)::numeric desc limit 1;
if p is null then select (e ->> 1)::numeric into p from jsonb_array_elements(tabla -> 'km') e order by (e ->> 0)::numeric limit 1; end if;
return p;
end $$;

create or replace function rodar.precio_tabla_espera(tabla jsonb, seg numeric) returns numeric language plpgsql immutable set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare mi int := floor(greatest(0, coalesce(seg, 0)) / 60); p numeric; lm int; lp numeric;
cada int := greatest(1, coalesce((tabla -> 'espera_extra' ->> 'cada_min')::int, 5)); monto numeric := coalesce((tabla -> 'espera_extra' ->> 'monto')::numeric, 0);
begin
if jsonb_array_length(coalesce(tabla -> 'espera', '[]')) = 0 then return 0; end if;
select (e ->> 0)::int, (e ->> 1)::numeric into lm, lp from jsonb_array_elements(tabla -> 'espera') e order by (e ->> 0)::int desc limit 1;
if mi > lm then return lp + floor((mi - lm)::numeric / cada) * monto; end if;
select (e ->> 1)::numeric into p from jsonb_array_elements(tabla -> 'espera') e where (e ->> 0)::int <= mi order by (e ->> 0)::int desc limit 1;
return coalesce(p, 0);
end $$;

create or replace function rodar.calcular_monto(t rodar.tarifas, metros numeric, espera_seg numeric, indice numeric default 1) returns numeric language plpgsql immutable set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare m numeric; red int; fd int; fe int := 0;
begin
if t.id is null then return 0; end if;
if jsonb_array_length(coalesce(t.tabla -> 'km', '[]')) > 0 then
return round((rodar.precio_tabla_km(t.tabla, greatest(0, coalesce(metros, 0) - coalesce(t.cortesia_mts, 0)))
+ case when t.con_espera then rodar.precio_tabla_espera(t.tabla, greatest(0, coalesce(espera_seg, 0) - coalesce(t.cortesia_min, 0) * 60)) else 0 end) * coalesce(indice, 1));
end if;
red := greatest(1, coalesce(t.redondeo_mts, 100));
m := greatest(0, coalesce(metros, 0) - coalesce(t.cortesia_mts, 0));
m := ceil(m / red) * red;
fd := floor(m / greatest(1, coalesce(t.ficha_mts, 100)));
if t.con_espera then fe := floor(greatest(0, coalesce(espera_seg, 0) - coalesce(t.cortesia_min, 0) * 60) / greatest(1, coalesce(t.espera_seg, 60))); end if;
return round((coalesce(t.bajada, 0) + (fd + fe) * coalesce(t.precio_ficha, 0)) * coalesce(indice, 1));
end $$;

-- guardar la tabla desde la pantalla de Tarifas
create or replace function public.r_tarifa_tabla(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare tb jsonb := p_b -> 'tabla';
begin
perform rodar.need(p_token, 'admin');
if tb is not null and jsonb_typeof(tb) <> 'object' then raise exception 'Tabla inválida'; end if;
update rodar.tarifas set tabla = case when jsonb_array_length(coalesce(tb -> 'km', '[]')) > 0 then tb end,
bajada = coalesce((tb -> 'km' -> 0 ->> 1)::numeric, bajada) where id = (p_q ->> 'id')::bigint;
perform rodar.emit('flota', 'tarifas', '{}');
return '{"ok":true}';
end $$;
grant execute on function public.r_tarifa_tabla(text, jsonb, jsonb) to anon, authenticated;

-- Tarifa de la remisería (tabla de la foto): todos los días, todo el día. Las demás quedan desactivadas.
do $$ declare tb jsonb := '{"km":[[1.0,4500],[1.1,5000],[1.2,5000],[1.3,5000],[1.4,5000],[1.5,5000],[1.6,5500],[1.7,5500],[1.8,5500],[1.9,5500],[2.0,6000],[2.1,6000],[2.2,6000],[2.3,6500],[2.4,6500],[2.5,6500],[2.6,7000],[2.7,7000],[2.8,7000],[2.9,7000],[3.0,8000],[3.1,8000],[3.2,8000],[3.3,8500],[3.4,8500],[3.5,8500],[3.6,9000],[3.7,9000],[3.8,9000],[3.9,9000],[4.0,9500],[4.1,9500],[4.2,9500],[4.3,9500],[4.4,10000],[4.5,10000],[4.6,10000],[4.7,10000],[4.8,10500],[4.9,10500],[5.0,10500],[5.1,10500],[5.2,11000],[5.3,11000],[5.4,11000],[5.5,11000],[5.6,11500],[5.7,11500],[5.8,11500],[5.9,11500],[6.0,12000],[6.1,12000],[6.2,12000],[6.3,12000],[6.4,12500],[6.5,12500],[6.6,12500],[6.7,12500],[6.8,13000],[6.9,13000],[7.0,13000],[7.1,13000],[7.2,13500],[7.3,13500],[7.4,13500],[7.5,13500],[7.6,14000],[7.7,14000],[7.8,14000],[7.9,14000],[8.0,15000],[8.1,15000],[8.2,15000],[8.3,15000],[8.4,15500],[8.5,15500],[8.6,15500],[8.7,15500],[8.8,16000],[8.9,16000],[9.0,16000],[9.1,16000],[9.2,16500],[9.3,16500],[9.4,16500],[9.5,16500],[9.6,17000],[9.7,17000],[9.8,17000],[9.9,17000]],"extra":{"cada_m":400,"monto":500},"espera":[[5,1500],[10,2500],[15,2500],[20,3000],[25,3500],[30,4000],[35,4500],[40,5000],[45,5500],[50,6000],[55,6500],[60,7000]],"espera_extra":{"cada_min":5,"monto":500}}'::jsonb; tid bigint;
begin
select id into tid from rodar.tarifas where nombre = 'Tarifa por km (tabla)';
if tid is null then
insert into rodar.tarifas(orden, nombre, tipo, activa, bajada, precio_ficha, con_espera, cortesia_mts, cortesia_min, dias, feriado, hora_desde, hora_hasta, tabla)
values (1, 'Tarifa por km (tabla)', 'fija', true, 4500, 0, true, 0, 0, '[1,2,3,4,5,6,0]', true, '00:00', '23:59', tb) returning id into tid;
update rodar.tarifas set activa = false where id <> tid;
else
update rodar.tarifas set tabla = tb, bajada = 4500 where id = tid;
end if;
end $$;
notify pgrst, 'reload schema';


-- ======== 11_cuentas_clientes.sql ========
-- Cuentas de clientes (app de pasajeros): email + contraseña, mis viajes, lugares guardados, reservas y perfil.
alter table rodar.clientes add column if not exists email text;
alter table rodar.clientes add column if not exists password_hash text;
alter table rodar.clientes add column if not exists cuenta_creada timestamp;
alter table rodar.clientes add column if not exists medio_pago_pref text;
create unique index if not exists ux_clientes_email on rodar.clientes (lower(email)) where email is not null;
alter table rodar.cliente_domicilios add column if not exists etiqueta text;
create table if not exists rodar.sesiones_clientes (
  token text primary key, cliente_id bigint not null, inicio timestamp, ultimo timestamp, activa boolean default true
);
create index if not exists ix_ses_cli on rodar.sesiones_clientes(cliente_id);

create or replace function rodar.cliente_sesion(p_token text) returns rodar.clientes language plpgsql as $$
#variable_conflict use_variable

declare s rodar.sesiones_clientes; c rodar.clientes;
begin
  select * into s from rodar.sesiones_clientes where token = p_token and activa;
  if not found then raise exception 'SESION_VENCIDA'; end if;
  select * into c from rodar.clientes where id = s.cliente_id and email is not null and baja_at is null;
  if not found then raise exception 'SESION_VENCIDA'; end if;
  if c.bloqueado then raise exception 'Tu cuenta está bloqueada. Comunicate con la central.'; end if;
  if s.ultimo is null or s.ultimo < rodar.ahora() - interval '1 minute' then update rodar.sesiones_clientes set ultimo = rodar.ahora() where token = p_token; end if;
  return c;
end $$;

create or replace function rodar.cliente_publico(c rodar.clientes) returns jsonb language sql stable as $$
  select jsonb_build_object('id', c.id, 'nombre', c.alias, 'email', c.email, 'telefono', c.telefono, 'medio_pago_pref', c.medio_pago_pref, 'desde', c.cuenta_creada,
    'lugares', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'etiqueta', d.etiqueta, 'direccion', d.direccion, 'localidad', d.localidad, 'provincia', d.provincia, 'referencias', d.referencias, 'lat', d.lat, 'lng', d.lng) order by d.etiqueta)
      from rodar.cliente_domicilios d where d.cliente_id = c.id and d.etiqueta is not null), '[]'),
    'recientes', coalesce((select jsonb_agg(x) from (select jsonb_build_object('id', d.id, 'direccion', d.direccion, 'localidad', d.localidad, 'provincia', d.provincia, 'lat', d.lat, 'lng', d.lng) x
      from rodar.cliente_domicilios d where d.cliente_id = c.id and d.lat is not null order by d.ultimo_uso desc nulls last limit 6) z), '[]'))
$$;

create or replace function rodar.nueva_sesion_cliente(p_cliente bigint) returns text language plpgsql as $$
#variable_conflict use_variable

declare tk text := rodar.token();
begin
  insert into rodar.sesiones_clientes(token, cliente_id, inicio, ultimo) values (tk, p_cliente, rodar.ahora(), rodar.ahora());
  return tk;
end $$;

create or replace function rodar.limitar(p_clave text, p_max int, p_ventana interval, p_msj text) returns void language plpgsql as $$
#variable_conflict use_variable

begin
  if (select count(*) from rodar.limite_pedidos where clave = p_clave and ts > now() - p_ventana) >= p_max then raise exception '%', p_msj; end if;
  insert into rodar.limite_pedidos(clave) values (p_clave);
end $$;

create or replace function public.r_cli_registro(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare nom text := trim(coalesce(p_b ->> 'nombre', '')); em text := lower(trim(coalesce(p_b ->> 'email', ''))); tel text := regexp_replace(coalesce(p_b ->> 'telefono', ''), '\D', '', 'g');
pw text := coalesce(p_b ->> 'password', ''); c rodar.clientes;
begin
  if nom = '' then raise exception 'Escribí tu nombre'; end if;
  if em !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Revisá el email: no parece válido'; end if;
  if length(tel) < 8 then raise exception 'Escribí tu celular con característica (ej. 3454 123456)'; end if;
  if length(pw) < 6 then raise exception 'La contraseña tiene que tener al menos 6 caracteres'; end if;
  perform rodar.limitar('registro', 30, interval '1 hour', 'Hay muchos registros en este momento, probá en unos minutos.');
  if exists(select 1 from rodar.clientes where lower(email) = em) then raise exception 'Ya hay una cuenta con ese email. Tocá "Ingresar" o "Olvidé mi contraseña".'; end if;
  select * into c from rodar.clientes where telefono = tel;
  if found then
    if c.email is not null then raise exception 'Ese celular ya tiene una cuenta con otro email. Si es tuyo, comunicate con la central.'; end if;
    if c.bloqueado then raise exception 'No podemos crear la cuenta. Comunicate con la central.'; end if;
    update rodar.clientes set email = em, password_hash = rodar.hash(pw), alias = nom, cuenta_creada = rodar.ahora(), baja_at = null where id = c.id returning * into c;
  else
    insert into rodar.clientes(telefono, alias, email, password_hash, cuenta_creada, creado) values (tel, nom, em, rodar.hash(pw), rodar.ahora(), rodar.ahora()) returning * into c;
  end if;
  return jsonb_build_object('token', rodar.nueva_sesion_cliente(c.id), 'cliente', rodar.cliente_publico(c));
end $$;

create or replace function public.r_cli_login(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare em text := lower(trim(coalesce(p_b ->> 'email', ''))); c rodar.clientes;
begin
  if (select count(*) from rodar.limite_pedidos where clave = 'login:' || em and ts > now() - interval '15 minutes') >= 8 then
    raise exception 'Demasiados intentos. Esperá 15 minutos o tocá "Olvidé mi contraseña".'; end if;
  select * into c from rodar.clientes where lower(email) = em;
  if not found or c.password_hash is null or not rodar.verificar(coalesce(p_b ->> 'password', ''), c.password_hash) then
    insert into rodar.limite_pedidos(clave) values ('login:' || em);
    raise exception 'El email o la contraseña no coinciden';
  end if;
  if c.bloqueado then raise exception 'Tu cuenta está bloqueada. Comunicate con la central.'; end if;
  if c.baja_at is not null then update rodar.clientes set baja_at = null where id = c.id returning * into c; end if;
  return jsonb_build_object('token', rodar.nueva_sesion_cliente(c.id), 'cliente', rodar.cliente_publico(c));
end $$;

create or replace function public.r_cli_logout(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

begin update rodar.sesiones_clientes set activa = false where token = p_token; return '{"ok":true}'; end $$;

create or replace function public.r_cli_perfil(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c rodar.clientes := rodar.cliente_sesion(p_token);
begin return rodar.cliente_publico(c); end $$;

create or replace function public.r_cli_perfil_guardar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c rodar.clientes := rodar.cliente_sesion(p_token); nom text := trim(coalesce(p_b ->> 'nombre', c.alias)); em text := lower(trim(coalesce(p_b ->> 'email', c.email)));
tel text := regexp_replace(coalesce(p_b ->> 'telefono', c.telefono), '\D', '', 'g');
begin
  if nom = '' then raise exception 'Escribí tu nombre'; end if;
  if em !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Revisá el email: no parece válido'; end if;
  if length(tel) < 8 then raise exception 'Escribí tu celular con característica'; end if;
  if em <> lower(c.email) and exists(select 1 from rodar.clientes where lower(email) = em and id <> c.id) then raise exception 'Ese email ya está en otra cuenta'; end if;
  if tel <> c.telefono and exists(select 1 from rodar.clientes where telefono = tel and id <> c.id) then raise exception 'Ese celular ya está registrado. Comunicate con la central para unificarlo.'; end if;
  if rodar.t(p_b, 'password_nueva') is not null then
    if not rodar.verificar(coalesce(p_b ->> 'password_actual', ''), c.password_hash) then raise exception 'La contraseña actual no es correcta'; end if;
    if length(p_b ->> 'password_nueva') < 6 then raise exception 'La nueva contraseña tiene que tener al menos 6 caracteres'; end if;
    update rodar.clientes set password_hash = rodar.hash(p_b ->> 'password_nueva') where id = c.id;
  end if;
  update rodar.clientes set alias = nom, email = em, telefono = tel, medio_pago_pref = coalesce(rodar.t(p_b, 'medio_pago_pref'), medio_pago_pref) where id = c.id returning * into c;
  return rodar.cliente_publico(c);
end $$;

create or replace function public.r_cli_viajes(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c rodar.clientes := rodar.cliente_sesion(p_token); lim int := least(100, coalesce(rodar.n(p_q, 'limite'), 30)::int);
begin
  return coalesce((select jsonb_agg(x order by orden, creado desc) from (
    select v.id, v.creado, v.programado, v.estado, v.origen_dir, v.origen_ref, v.origen_lat, v.origen_lng, v.destino_dir, v.destino_lat, v.destino_lng,
      coalesce(v.monto, v.monto_estimado) monto, v.monto is not null monto_final, v.km, v.minutos, v.medio_pago, v.calificacion, v.inicio_at, v.fin_at, v.motivo_anulacion,
      m.numero movil_numero, m.patente, trim(coalesce(m.marca, '') || ' ' || coalesce(m.modelo, '')) movil, rodar.firma(v.id) k,
      case when v.estado in ('pendiente', 'ofrecido', 'confirmado', 'en_curso') then 0 when v.estado = 'reserva' then 1 else 2 end orden
    from rodar.viajes v left join rodar.moviles m on m.id = v.movil_id
    where v.cliente_id = c.id and v.creado >= c.cuenta_creada - interval '1 minute'
    order by orden, v.creado desc limit lim) x), '[]');
end $$;

create or replace function public.r_cli_viaje(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c rodar.clientes := rodar.cliente_sesion(p_token); prog timestamp := rodar.ts(p_b, 'programado'); medio text := coalesce(rodar.t(p_b, 'medio_pago'), c.medio_pago_pref, 'efectivo'); ids bigint[];
begin
  if rodar.t(p_b, 'origen_dir') is null or p_b ->> 'origen_lat' is null then raise exception 'Indicá el origen en el mapa o buscá la dirección'; end if;
  if prog is not null then
    if prog < rodar.ahora() + interval '15 minutes' then raise exception 'Para reservar elegí un horario con al menos 15 minutos de anticipación (o pedí "Ahora").'; end if;
    if prog > rodar.ahora() + interval '60 days' then raise exception 'Se puede reservar hasta 60 días antes'; end if;
    if (select count(*) from rodar.viajes where cliente_id = c.id and estado = 'reserva') >= 10 then raise exception 'Tenés muchas reservas pendientes. Cancelá alguna o llamá a la central.'; end if;
  elsif (select count(*) from rodar.viajes where cliente_id = c.id and estado in ('pendiente', 'ofrecido', 'confirmado', 'en_curso')) >= 2 then
    raise exception 'Ya tenés viajes en curso. Si necesitás otro móvil, llamá a la central.';
  end if;
  perform rodar.limitar('cli:' || c.id, 6, interval '10 minutes', 'Demasiados pedidos seguidos. Esperá unos minutos o llamá a la central.');
  ids := rodar.crear_viaje(p_b || jsonb_build_object('telefono', c.telefono, 'alias', c.alias, 'canal', 'aplicacion', 'medio_pago', medio, 'pin_requerido', true,
    'cantidad_moviles', 1, 'estado', 'pendiente', 'movil_id', null, 'conductor_id', null, 'monto_fijo', null, 'corporativo_id', null, 'a_oferta', false, 'origen_tipo', 'central', 'datos_movil', null,
    'programado', case when prog is null then null else to_char(prog, 'YYYY-MM-DD HH24:MI:SS') end), null);
  update rodar.clientes set medio_pago_pref = medio where id = c.id;
  perform rodar.procesar();
  return jsonb_build_object('id', ids[1], 'k', rodar.firma(ids[1]), 'reserva', prog is not null, 'canal', rodar.topico('viaje-' || ids[1] || '-' || rodar.firma(ids[1])));
end $$;

create or replace function public.r_cli_cancelar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c rodar.clientes := rodar.cliente_sesion(p_token); v rodar.viajes; nada rodar.usuarios;
begin
  select * into v from rodar.viajes where id = (p_q ->> 'id')::bigint and cliente_id = c.id;
  if not found then raise exception 'No encontramos ese viaje'; end if;
  if v.estado not in ('reserva', 'pendiente', 'ofrecido', 'confirmado') then raise exception 'Ese viaje ya no se puede cancelar'; end if;
  perform rodar.anular(v.id, nada, case when v.estado = 'reserva' then 'Reserva cancelada por el cliente' else 'Cancelado por el cliente' end);
  return '{"ok":true}';
end $$;

create or replace function public.r_cli_lugar_guardar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c rodar.clientes := rodar.cliente_sesion(p_token); et text := trim(coalesce(p_b ->> 'etiqueta', '')); did bigint := rodar.n(p_b, 'id')::bigint; dir text := rodar.t(p_b, 'direccion');
begin
  if et = '' then raise exception 'Poné un nombre, por ejemplo Casa o Trabajo'; end if;
  if did is null and dir is not null then select id into did from rodar.cliente_domicilios where cliente_id = c.id and direccion = dir order by id limit 1; end if;
  if did is not null then
    update rodar.cliente_domicilios set etiqueta = left(et, 30), direccion = coalesce(dir, direccion), lat = coalesce((p_b ->> 'lat')::float8, lat), lng = coalesce((p_b ->> 'lng')::float8, lng),
      localidad = coalesce(rodar.t(p_b, 'localidad'), localidad), provincia = coalesce(rodar.t(p_b, 'provincia'), provincia), referencias = coalesce(p_b ->> 'referencias', referencias)
    where id = did and cliente_id = c.id;
    if not found then raise exception 'No encontramos ese lugar'; end if;
  else
    if dir is null or p_b ->> 'lat' is null then raise exception 'Elegí la dirección en el buscador o en el mapa'; end if;
    if (select count(*) from rodar.cliente_domicilios where cliente_id = c.id and etiqueta is not null) >= 12 then raise exception 'Llegaste al máximo de lugares guardados'; end if;
    insert into rodar.cliente_domicilios(cliente_id, direccion, localidad, provincia, referencias, lat, lng, usos, ultimo_uso, etiqueta)
    values (c.id, dir, rodar.t(p_b, 'localidad'), rodar.t(p_b, 'provincia'), p_b ->> 'referencias', (p_b ->> 'lat')::float8, (p_b ->> 'lng')::float8, 0, null, left(et, 30));
  end if;
  return rodar.cliente_publico(c);
end $$;

create or replace function public.r_cli_lugar_quitar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c rodar.clientes := rodar.cliente_sesion(p_token);
begin
  update rodar.cliente_domicilios set etiqueta = null where id = (p_q ->> 'id')::bigint and cliente_id = c.id;
  return rodar.cliente_publico(c);
end $$;

create or replace function public.r_cli_olvide(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare em text := lower(trim(coalesce(p_b ->> 'email', ''))); c rodar.clientes; cid bigint;
begin
  perform rodar.limitar('olvide:' || em, 3, interval '1 hour', 'Ya recibimos tu pedido. La central se va a comunicar con vos.');
  select * into c from rodar.clientes where lower(email) = em;
  if found then
    insert into rodar.soporte_conv(tipo, cliente_tel, cliente_alias, asunto, no_leidos, actualizado) values ('cliente', c.telefono, c.alias, 'Recuperar contraseña de la app', 1, rodar.ahora()) returning id into cid;
    insert into rodar.soporte_msg(conv_id, de, texto, fecha) values (cid, 'cliente', 'Olvidé mi contraseña de la app. Email: ' || c.email || ' · Celular: ' || c.telefono ||
      '. (Para darle una clave nueva: Operador → cargar viaje → buscar el teléfono → botón "Cuenta app").', rodar.ahora());
    perform rodar.emit('panel', 'soporte', jsonb_build_object('conv', cid));
  end if;
  return '{"ok":true}';
end $$;

-- panel: ver y resetear la cuenta de la app de un cliente
create or replace function public.r_cliente_cuenta(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.need(p_token, 'operador'); c rodar.clientes; nueva text;
begin
  select * into c from rodar.clientes where id = (p_q ->> 'id')::bigint;
  if not found then raise exception 'No existe el cliente'; end if;
  if rodar.b(p_b, 'resetear') then
    if c.email is null then raise exception 'Este cliente todavía no creó su cuenta en la app'; end if;
    nueva := lpad((floor(random() * 1000000))::int::text, 6, '0');
    update rodar.clientes set password_hash = rodar.hash(nueva) where id = c.id;
    update rodar.sesiones_clientes set activa = false where cliente_id = c.id;
    perform rodar.accion(u, 'cliente_clave_app', c.telefono, 'Clave de la app reseteada');
  end if;
  return jsonb_build_object('tiene_cuenta', c.email is not null, 'email', c.email, 'desde', c.cuenta_creada, 'clave_nueva', nueva);
end $$;

-- no exponer el hash de la contraseña al panel
create or replace function public.r_clientes_buscar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare q text := trim(coalesce(p_q ->> 'q', ''));
begin
  perform rodar.need(p_token, 'operador');
  if q = '' then return '[]'; end if;
  return coalesce((select jsonb_agg(to_jsonb(c) - 'password_hash') from (select * from rodar.clientes where telefono ilike '%' || q || '%' or alias ilike '%' || q || '%' or email ilike '%' || q || '%'
    order by baja_at is not null, alias limit 15) c), '[]');
end $$;

create or replace function public.r_cliente_tel(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c rodar.clientes;
begin
  perform rodar.need(p_token, 'operador');
  select * into c from rodar.clientes where telefono = p_q ->> 'tel';
  if not found then return 'null'; end if;
  return to_jsonb(c) - 'password_hash' || jsonb_build_object(
    'domicilios', rodar.lista('select * from rodar.cliente_domicilios where cliente_id = ' || c.id || ' order by etiqueta is null, usos desc, ultimo_uso desc'),
    'ultimos', rodar.lista('select id, creado, estado, origen_dir, destino_dir, monto from rodar.viajes where cliente_id = ' || c.id || ' order by id desc limit 10'),
    'negativos', rodar.lista('select n.movil_id, m.numero from rodar.negativos n join rodar.moviles m on m.id = n.movil_id where n.cliente_id = ' || c.id),
    'reservas', rodar.lista('select id, programado, origen_dir from rodar.viajes where cliente_id = ' || c.id || ' and estado = ''reserva'' order by programado'));
end $$;

grant execute on function public.r_cli_registro(text, jsonb, jsonb), public.r_cli_login(text, jsonb, jsonb), public.r_cli_logout(text, jsonb, jsonb),
  public.r_cli_perfil(text, jsonb, jsonb), public.r_cli_perfil_guardar(text, jsonb, jsonb), public.r_cli_viajes(text, jsonb, jsonb), public.r_cli_viaje(text, jsonb, jsonb),
  public.r_cli_cancelar(text, jsonb, jsonb), public.r_cli_lugar_guardar(text, jsonb, jsonb), public.r_cli_lugar_quitar(text, jsonb, jsonb), public.r_cli_olvide(text, jsonb, jsonb),
  public.r_cliente_cuenta(text, jsonb, jsonb) to anon, authenticated;
revoke all on rodar.sesiones_clientes from anon, authenticated;
alter function rodar.cliente_sesion(text) set search_path = rodar, public, extensions;
alter function rodar.cliente_publico(rodar.clientes) set search_path = rodar, public, extensions;
alter function rodar.nueva_sesion_cliente(bigint) set search_path = rodar, public, extensions;
alter function rodar.limitar(text, int, interval, text) set search_path = rodar, public, extensions;
notify pgrst, 'reload schema';


-- ======== 12_direcciones.sql ========
-- Direcciones aprendidas: el mapa libre (OpenStreetMap) no tiene la numeración de muchas calles de Federal.
-- El sistema aprende la ubicación real de cada "calle + altura" con el GPS del chofer (al tocar "Llegué" y al finalizar)
-- y con eso ubica las direcciones repetidas y estima las alturas intermedias de la misma calle.
create table if not exists rodar.direcciones_conocidas (
  id bigint generated by default as identity primary key,
  calle text not null, calle_norm text not null, altura int not null, localidad text,
  lat double precision not null, lng double precision not null, usos int default 1, actualizado timestamp
);
create unique index if not exists ux_dir_conocida on rodar.direcciones_conocidas(calle_norm, altura);
create index if not exists ix_dir_conocida_calle on rodar.direcciones_conocidas(calle_norm);

create or replace function rodar.norm_calle(t text) returns text language sql immutable as $$
  select nullif(trim(regexp_replace(regexp_replace(regexp_replace(translate(lower(coalesce(t, '')), 'áéíóúüñ', 'aeiouun'),
    '^(calle|avenida|av\.?|bv\.?|bvard\.?|boulevard|pje\.?|pasaje|diagonal|diag\.?)\s+', ''), '[^a-z0-9 ]', ' ', 'g'), '\s+', ' ', 'g')), '')
$$;

-- "San Martín 450, Federal" -> calle "San Martín", altura 450 ("25 de Mayo 300" -> "25 de Mayo", 300)
create or replace function rodar.separar_dir(d text, out calle text, out altura int) language plpgsql immutable as $$
#variable_conflict use_variable

declare m text[]; base text := trim(split_part(coalesce(d, ''), ',', 1));
begin
  m := regexp_match(base, '^(.+?)\s+(?:n(?:ro|°|º)?\.?\s*)?(\d{1,5})$', 'i');
  if m is null then calle := nullif(base, ''); altura := null; else calle := trim(m[1]); altura := m[2]::int; end if;
end $$;

create or replace function rodar.aprender_dir(p_dir text, p_lat float8, p_lng float8, p_loc text) returns void language plpgsql as $$
#variable_conflict use_variable

declare s record; cn text;
begin
  if p_lat is null or p_lng is null then return; end if;
  s := rodar.separar_dir(p_dir); cn := rodar.norm_calle(s.calle);
  if s.altura is null or s.altura <= 0 or cn is null then return; end if;
  insert into rodar.direcciones_conocidas(calle, calle_norm, altura, localidad, lat, lng, usos, actualizado)
  values (s.calle, cn, s.altura, p_loc, p_lat, p_lng, 1, rodar.ahora())
  on conflict (calle_norm, altura) do update set
    lat = (rodar.direcciones_conocidas.lat * least(rodar.direcciones_conocidas.usos, 9) + excluded.lat) / (least(rodar.direcciones_conocidas.usos, 9) + 1),
    lng = (rodar.direcciones_conocidas.lng * least(rodar.direcciones_conocidas.usos, 9) + excluded.lng) / (least(rodar.direcciones_conocidas.usos, 9) + 1),
    usos = rodar.direcciones_conocidas.usos + 1, actualizado = excluded.actualizado;
end $$;

-- aprende con el GPS real del móvil (no con móviles simulados)
create or replace function rodar.trg_aprender_dir() returns trigger language plpgsql as $$
#variable_conflict use_variable

declare m rodar.moviles;
begin
  begin
    select * into m from rodar.moviles where id = new.movil_id;
    if not found or m.simulado or m.lat is null then return new; end if;
    if new.llegada_at is not null and old.llegada_at is null
       and (new.origen_lat is null or rodar.dist(m.lat, m.lng, new.origen_lat, new.origen_lng) < 600) then
      perform rodar.aprender_dir(new.origen_dir, m.lat, m.lng, new.origen_loc);
    end if;
    if new.estado = 'finalizado' and old.estado is distinct from 'finalizado' and new.destino_dir is not null then
      perform rodar.aprender_dir(new.destino_dir, m.lat, m.lng, new.destino_loc);
    end if;
  exception when others then null; -- nunca frena un viaje
  end;
  return new;
end $$;
create or replace trigger viajes_aprender_dir after update of llegada_at, estado on rodar.viajes for each row execute function rodar.trg_aprender_dir();

-- búsqueda: exacta, interpolada entre dos alturas conocidas de la misma calle, o la más cercana
create or replace function public.r_dir_buscar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare s record; cn text; a rodar.direcciones_conocidas; b rodar.direcciones_conocidas; f float8;
begin
  s := rodar.separar_dir(p_q ->> 'q'); cn := rodar.norm_calle(s.calle);
  if cn is null or s.altura is null then return 'null'; end if;
  select * into a from rodar.direcciones_conocidas where calle_norm = cn and altura <= s.altura order by altura desc limit 1;
  select * into b from rodar.direcciones_conocidas where calle_norm = cn and altura >= s.altura order by altura limit 1;
  if a.id is not null and a.altura = s.altura then
    return jsonb_build_object('calle', a.calle, 'altura', s.altura, 'lat', a.lat, 'lng', a.lng, 'localidad', a.localidad, 'precision', 'exacta');
  end if;
  if a.id is not null and b.id is not null and b.altura - a.altura <= 1500 then
    f := (s.altura - a.altura)::float8 / nullif(b.altura - a.altura, 0);
    return jsonb_build_object('calle', a.calle, 'altura', s.altura, 'lat', a.lat + (b.lat - a.lat) * f, 'lng', a.lng + (b.lng - a.lng) * f, 'localidad', a.localidad, 'precision', 'estimada');
  end if;
  a := coalesce(a, b);
  if a.id is null then select * into a from rodar.direcciones_conocidas where calle_norm = cn order by abs(altura - s.altura) limit 1; end if;
  if a.id is not null and abs(a.altura - s.altura) <= 200 then
    return jsonb_build_object('calle', a.calle, 'altura', s.altura, 'lat', a.lat, 'lng', a.lng, 'localidad', a.localidad, 'precision', 'cercana');
  end if;
  return 'null';
end $$;

-- al tocar el mapa: dirección conocida más cercana (para sugerir la altura)
create or replace function public.r_dir_cercana(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare lat float8 := (p_q ->> 'lat')::float8; lng float8 := (p_q ->> 'lng')::float8; d rodar.direcciones_conocidas; dist float8;
begin
  if lat is null or lng is null then return 'null'; end if;
  select x.* into d from rodar.direcciones_conocidas x
  where x.lat between lat - 0.002 and lat + 0.002 and x.lng between lng - 0.0025 and lng + 0.0025
  order by rodar.dist(x.lat, x.lng, lat, lng) limit 1;
  if d.id is null then return 'null'; end if;
  dist := rodar.dist(d.lat, d.lng, lat, lng);
  if dist > 70 then return 'null'; end if;
  return jsonb_build_object('calle', d.calle, 'altura', d.altura, 'localidad', d.localidad, 'metros', round(dist::numeric));
end $$;

grant execute on function public.r_dir_buscar(text, jsonb, jsonb), public.r_dir_cercana(text, jsonb, jsonb) to anon, authenticated;
revoke all on rodar.direcciones_conocidas from anon, authenticated;
alter function rodar.norm_calle(text) set search_path = rodar, public, extensions;
alter function rodar.separar_dir(text) set search_path = rodar, public, extensions;
alter function rodar.aprender_dir(text, float8, float8, text) set search_path = rodar, public, extensions;
alter function rodar.trg_aprender_dir() set search_path = rodar, public, extensions;

-- punto de partida: las direcciones con altura de los viajes reales ya terminados (con GPS del chofer al llegar)
do $$ declare v record; begin
  for v in select vj.origen_dir, vj.origen_loc, p.lat, p.lng from rodar.viajes vj join rodar.moviles m on m.id = vj.movil_id and not m.simulado
    join lateral (select lat, lng from rodar.posiciones where movil_id = vj.movil_id and ts between vj.llegada_at - interval '20 seconds' and vj.llegada_at + interval '20 seconds' order by abs(extract(epoch from ts - vj.llegada_at)) limit 1) p on true
    where vj.llegada_at is not null loop
    perform rodar.aprender_dir(v.origen_dir, v.lat, v.lng, v.origen_loc);
  end loop;
end $$;
notify pgrst, 'reload schema';


-- ======== 13_borrado.sql ========
-- ===================== Eliminar móvil y reiniciar el sistema =====================

-- Elimina un móvil (solo admin). Se rechaza si tiene un viaje en curso u ofrecido.
-- Los viajes ya terminados quedan en el historial.
create or replace function public.r_movil_borrar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.need(p_token, 'admin'); mid bigint := rodar.n(p_q, 'id')::bigint; m rodar.moviles;
begin
  select * into m from rodar.moviles where id = mid;
  if not found then raise exception 'El móvil no existe'; end if;
  if exists(select 1 from rodar.viajes where movil_id = mid and estado in ('ofrecido', 'confirmado', 'en_curso')) then
    raise exception 'El móvil % tiene un viaje en curso. Esperá a que termine o anulalo antes de eliminarlo.', m.numero;
  end if;
  update rodar.sesiones set activa = false where movil_id = mid;
  delete from rodar.movil_conductores where movil_id = mid;
  delete from rodar.penalizaciones where movil_id = mid;
  delete from rodar.cuenta_movimientos where movil_id = mid;
  delete from rodar.negativos where movil_id = mid;
  delete from rodar.mp_saldo_mov where movil_id = mid;
  delete from rodar.posiciones where movil_id = mid;
  delete from rodar.sim_estado where movil_id = mid;
  delete from rodar.moviles where id = mid;
  perform rodar.accion(u, 'movil_eliminado', m.numero::text, 'Se eliminó el móvil ' || m.numero || coalesce(' (' || m.patente || ')', ''));
  perform rodar.emit('panel', 'movil_baja', jsonb_build_object('id', mid, 'numero', m.numero));
  return jsonb_build_object('ok', true);
end $$;

-- Deja el sistema en cero. Solo admin, con su contraseña y la frase de confirmación.
-- Se borran: viajes, clientes, móviles, usuarios (menos el admin que lo ejecuta), cuentas, chats, soporte, reportes,
-- informes, zonas, paradas, zonas peligrosas, corporativos, solicitudes de conductores y direcciones aprendidas.
-- Se conservan: datos de la empresa, tarifas, planes, módulos, canales, medios de pago, feriados y la cuenta del admin.
create or replace function public.r_sistema_reiniciar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.need(p_token, 'admin'); t text;
  tablas text[] := array['viajes', 'clientes', 'cliente_domicilios', 'negativos', 'sesiones_clientes', 'moviles', 'movil_conductores',
    'penalizaciones', 'cuenta_movimientos', 'mp_pagos', 'mp_saldo_mov', 'solicitudes_conductor', 'acciones_usuarios', 'eventos_moviles',
    'moviles_historial', 'posiciones', 'soporte_conv', 'soporte_msg', 'chat_conv', 'chat_msg', 'reportes', 'reporte_historial',
    'novedades_vistas', 'conexion_diaria', 'mensajes_flota', 'limite_pedidos', 'sim_estado', 'direcciones_conocidas', 'docs_generados',
    'zonas', 'zonas_peligrosas', 'corporativos'];
begin
  if not rodar.verificar(coalesce(p_b ->> 'password', ''), u.password_hash) then raise exception 'La contraseña no es correcta'; end if;
  if upper(trim(coalesce(p_b ->> 'confirmacion', ''))) <> 'BORRAR TODO' then raise exception 'Escribí BORRAR TODO para confirmar'; end if;
  foreach t in array tablas loop
    if to_regclass('rodar.' || t) is not null then execute format('truncate table rodar.%I restart identity cascade', t); end if;
  end loop;
  delete from rodar.sesiones where usuario_id <> u.id;
  delete from rodar.usuarios where id <> u.id;
  update rodar.usuarios set corporativo_id = null where id = u.id;
  perform rodar.cfg_set('simulador', '{"flota":false,"demanda":false}');
  perform rodar.accion(u, 'sistema_reiniciado', null, 'Se borraron todos los datos y el sistema quedó en cero');
  return jsonb_build_object('ok', true);
end $$;

notify pgrst, 'reload schema';


-- ======== 14_plan_diario.sql ========
-- ===================== Plan con cuota diaria =====================
-- El móvil paga un monto por día para poder trabajar. Cada día, a la "hora de cobro" del plan, se descuenta la cuota de su cuenta.
-- Estados de la cuenta (rodar.estado_cuenta):
--   Al día                  saldo ≥ saldo mínimo del plan
--   Debajo del mínimo       saldo < mínimo del plan, pero todavía dentro de la tolerancia (sigue recibiendo viajes)
--   Bloqueado por deuda     la deuda superó la tolerancia: no recibe viajes. Tolerancia = días completos de "Horas de tolerancia" (48 h = 2 cuotas)
--   Inhabilitado / fuera de servicio   y   Habilitado sin plan: igual que antes.
-- Una prórroga vigente sigue evitando el bloqueo.

create or replace function rodar.estado_cuenta(m rodar.moviles) returns jsonb language plpgsql stable as $$
#variable_conflict use_variable

declare p rodar.planes; s numeric; lim numeric; pr boolean; color text := 'verde'; texto text := 'Al día'; diaria boolean;
begin
  select * into p from rodar.planes where id = m.plan_id;
  s := rodar.saldo(m.id);
  lim := coalesce((rodar.cfg('dispatch') ->> 'deuda_bloqueo')::numeric, -5000);
  pr := m.prorroga_hasta is not null and m.prorroga_hasta > rodar.ahora();
  diaria := p.id is not null and not p.sistema and p.periodicidad = 'diaria' and coalesce(p.monto_fijo, 0) > 0;
  if not m.habilitado or m.estado = 'fuera_servicio' then color := 'gris'; texto := 'Inhabilitado / fuera de servicio';
  elsif p.id is null or p.sistema then color := 'azul'; texto := 'Habilitado sin plan';
  elsif diaria and s < -(p.monto_fijo * floor(coalesce(p.horas_bloqueo, 0) / 24.0)) and not pr then color := 'rojo'; texto := 'Bloqueado por deuda';
  elsif not diaria and s <= lim and not pr then color := 'rojo'; texto := 'Bloqueado por deuda';
  elsif s < coalesce(p.minimo, 0) then color := 'amarillo'; texto := 'Debajo del mínimo'; end if;
  return jsonb_build_object('saldo', s, 'color', color, 'texto', texto, 'plan', case when p.id is null then null else to_jsonb(p) end,
    'prorroga', case when pr then m.prorroga_hasta end, 'bloqueado', color = 'rojo',
    'sin_saldo', p.id is not null and p.modo_pago = 'prepago' and p.modo_cobro <> 'fijo' and s <= 0 and not p.sistema);
end $$;

-- Cobro de cuotas, ahora también diario. La cuota diaria se cobra una vez por día a partir de la hora de cobro
-- (si el sistema no corrió justo en esa hora, se cobra apenas vuelve a correr ese mismo día).
create or replace function rodar.ciclo_cuotas() returns void language plpgsql as $$
#variable_conflict use_variable

declare p rodar.planes; m rodar.moviles; d timestamp := rodar.ahora(); toca boolean; periodo text; sv numeric; n int;
begin
  for p in select * from rodar.planes where not sistema and monto_fijo > 0 loop
    if p.periodicidad = 'diaria' then
      if extract(hour from d)::int < p.hora_cobro then continue; end if;
    elsif extract(hour from d)::int <> p.hora_cobro then continue; end if;
    toca := false;
    if p.periodicidad = 'diaria' then toca := true; periodo := d::date::text; end if;
    if p.periodicidad = 'semanal' and extract(dow from d)::int = p.dia_semana then toca := true; periodo := d::date::text; end if;
    if p.periodicidad = 'mensual' and extract(day from d)::int = p.dia_mes then toca := true; periodo := to_char(d, 'YYYY-MM'); end if;
    if p.periodicidad = 'quincenal' and extract(day from d)::int in (p.dia_mes, p.dia_mes + 15) then toca := true; periodo := d::date::text; end if;
    if not toca or rodar.cfg('cobro_plan_' || p.id) #>> '{}' = periodo then continue; end if;
    perform rodar.cfg_set('cobro_plan_' || p.id, to_jsonb(periodo));
    n := 0;
    for m in select * from rodar.moviles where plan_id = p.id and habilitado loop
      if p.tipo1 and p.vencer_saldo then
        select coalesce(sum(monto), 0) into sv from rodar.cuenta_movimientos where movil_id = m.id and tipo in ('saldo_viajes', 'viaje') and fecha >= d - interval '31 days';
        if sv > 0 then perform rodar.movimiento(m.id, 'vencimiento', -sv, 'Vence saldo prepago del período', null, null); end if;
      end if;
      perform rodar.movimiento(m.id, 'cuota', -p.monto_fijo, 'Cuota ' || p.descripcion || ' ' || periodo, null, null);
      perform rodar.cfg_set('tipo1_pend_' || m.id, to_jsonb(p.tipo1));
      perform rodar.emitir_movil(m.id);
      n := n + 1;
    end loop;
    insert into rodar.acciones_usuarios(fecha, actor, tipo, afectado, detalle) values (d, 'sistema', 'cobro_cuotas', p.descripcion, n || ' móviles');
  end loop;
end $$;

-- Plan de ejemplo (solo si no existe). Editá el monto en Administración → Planes. No afecta a ningún móvil hasta que se lo asignes.
insert into rodar.planes(descripcion, modo_pago, modo_cobro, monto_fijo, periodicidad, hora_cobro, horas_bloqueo, minimo)
select 'Cuota diaria', 'prepago', 'fijo', 5000, 'diaria', 0, 48, 0
where not exists (select 1 from rodar.planes where descripcion = 'Cuota diaria' and not sistema);

