-- ======== 16_distancia_viaje.sql ========
-- ===================== Distancia del viaje más confiable =====================
-- Problema: el tarifador de la app suma los metros del GPS del celular. Si el celular tiene la pantalla apagada o la app en segundo plano,
-- el GPS "salta" y la app descartaba esos tramos: un viaje de ~3 km terminaba cobrando la tarifa mínima.
-- Solución: al finalizar, el servidor calcula la distancia con las posiciones que el móvil fue enviando durante el viaje
-- y con la distancia en línea recta (x1,15) origen → destino, y cobra la MAYOR entre eso y lo que midió la app.

-- Suma de tramos entre posiciones registradas. Ignora el ruido del GPS parado (< 15 m) y los saltos imposibles (> 150 km/h).
create or replace function rodar.metros_recorridos(p_movil bigint, p_desde timestamp, p_hasta timestamp) returns numeric language sql stable as $$
  select coalesce(sum(d), 0)::numeric from (
    select rodar.dist(lag(lat) over w, lag(lng) over w, lat, lng) d, extract(epoch from ts - lag(ts) over w) dt
    from rodar.posiciones where movil_id = p_movil and ts between p_desde and p_hasta window w as (order by ts)
  ) x where d >= 15 and (dt is null or dt <= 0 or d <= dt * 41.7) $$;

create or replace function rodar.finalizar(p_viaje bigint, p_metros numeric, p_espera numeric, p_monto numeric, dlat float8 default null, dlng float8 default null, ddir text default null) returns jsonb language plpgsql as $$
#variable_conflict use_variable

declare v rodar.viajes; t rodar.tarifas; c rodar.canales; total numeric := p_monto; mins numeric; mp jsonb; tasa numeric; dias int; vf rodar.viajes; metros numeric := p_metros; mpos numeric; recta numeric; sim boolean;
begin
  select * into v from rodar.viajes where id = p_viaje;
  if not found or v.estado not in ('en_curso', 'confirmado') then raise exception 'El viaje no está en curso'; end if;
  select * into t from rodar.tarifas where id = v.tarifa_id;
  if t.id is null then t := rodar.tarifa_vigente(); end if;
  select * into c from rodar.canales where codigo = v.canal;
  -- Distancia: la app suma los metros del GPS del celular, pero si el celular estuvo en segundo plano o con la pantalla apagada
  -- pierde tramos y el viaje queda en la tarifa mínima. Se compara con el recorrido que registró el servidor y con la distancia en
  -- línea recta hasta el destino, y se cobra la mayor.
  select coalesce(simulado, false) into sim from rodar.moviles where id = v.movil_id;
  if p_metros is not null and not coalesce(sim, false) and v.inicio_at is not null then
    mpos := rodar.metros_recorridos(v.movil_id, v.inicio_at - interval '20 seconds', rodar.ahora());
    recta := case when v.origen_lat is not null and coalesce(dlat, v.destino_lat) is not null then rodar.dist(v.origen_lat, v.origen_lng, coalesce(dlat, v.destino_lat), coalesce(dlng, v.destino_lng)) * 1.15 end;
    metros := greatest(p_metros, coalesce(mpos, 0), coalesce(recta, 0));
  end if;
  if total is null then
    if c.cobro_modo = 'fijo' and v.monto_estimado is not null then total := v.monto_estimado;
    elsif c.cobro_modo = 'pagado' then total := 0;
    else total := rodar.calcular_monto(t, coalesce(metros, 0), coalesce(p_espera, 0), coalesce(v.indice, 1)); end if;
  end if;
  mins := round(extract(epoch from (rodar.ahora() - coalesce(v.inicio_at, rodar.ahora()))) / 60.0, 1);
  update rodar.viajes set estado = 'finalizado', fin_at = rodar.ahora(), monto = total, km = case when metros is not null then round(metros / 1000, 2) else km end,
    minutos = mins, espera_min = round(coalesce(p_espera, 0) / 60.0, 1), destino_lat = coalesce(destino_lat, dlat), destino_lng = coalesce(destino_lng, dlng), destino_dir = coalesce(destino_dir, ddir)
    where id = p_viaje returning * into vf;
  update rodar.moviles set estado = 'disponible' where id = v.movil_id;
  perform rodar.cobrar_viaje(vf);
  if vf.medio_pago = 'mercadopago' then
    mp := rodar.cfg('mp', '{}');
    tasa := coalesce((mp -> 'tasas' ->> coalesce(mp ->> 'plazo', 'inmediata'))::numeric, 0);
    dias := case coalesce(mp ->> 'plazo', 'inmediata') when 'd10' then 10 when 'd18' then 18 when 'd35' then 35 else 0 end;
    insert into rodar.mp_pagos(tipo, movil_id, viaje_id, monto, comision, estado, acreditado, liberacion, fecha)
    values ('viaje', vf.movil_id, vf.id, total, round(total * tasa / 100, 2), 'pendiente', false, rodar.hoy() + dias, rodar.ahora());
  end if;
  perform rodar.emitir_viaje(p_viaje); perform rodar.emitir_movil(v.movil_id);
  return rodar.viaje_detalle(p_viaje);
end $$;

notify pgrst, 'reload schema';


-- ======== 17_pagar_base.sql ========
-- ===================== Pagar base (Mercado Pago con acreditación automática) =====================

-- Datos para la pantalla "Pagar base": saldo, estado de la cuenta, cuota del plan y monto sugerido.
-- La app del conductor la llama con su sesión (móvil de la sesión); el panel pasa movil_id.
create or replace function public.r_base_info(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); s rodar.sesiones := rodar.sesion(p_token); m rodar.moviles; ec jsonb; p jsonb; sal numeric; cuota numeric; deuda numeric; sug numeric; mp jsonb := rodar.cfg('mp', '{}');
begin
  select * into m from rodar.moviles where id = coalesce(s.movil_id, rodar.n(p_q, 'movil_id')::bigint);
  if not found then raise exception 'Elegí un móvil'; end if;
  if not (m.titular_id = u.id or exists(select 1 from rodar.movil_conductores where movil_id = m.id and usuario_id = u.id) or rodar.tiene(u, 'admin')) then raise exception 'Sin permiso sobre ese móvil'; end if;
  ec := rodar.estado_cuenta(m); p := ec -> 'plan'; sal := (ec ->> 'saldo')::numeric;
  cuota := case when p is not null and not coalesce((p ->> 'sistema')::boolean, false) then coalesce((p ->> 'monto_fijo')::numeric, 0) else 0 end;
  deuda := greatest(0, -sal);
  sug := greatest(deuda, case when cuota > 0 then cuota - greatest(sal, 0) else 0 end, coalesce((p ->> 'minimo')::numeric, 0) - sal, 0);
  return jsonb_build_object('movil_id', m.id, 'numero', m.numero, 'saldo', sal, 'color', ec ->> 'color', 'texto', ec ->> 'texto', 'bloqueado', (ec ->> 'bloqueado')::boolean,
    'plan', case when p is null then null else jsonb_build_object('descripcion', p ->> 'descripcion', 'periodicidad', p ->> 'periodicidad', 'monto_fijo', cuota, 'minimo', p -> 'minimo', 'horas_bloqueo', p -> 'horas_bloqueo', 'sistema', p -> 'sistema') end,
    'deuda', deuda, 'cuota', cuota, 'sugerido', greatest(sug, 0), 'alias', nullif(mp ->> 'alias_cobro', ''), 'link', nullif(mp ->> 'link_pago', ''));
end $$;

-- La función de Supabase "mercadopago" avisa acá cuando Mercado Pago confirma un pago aprobado.
-- Acredita el pago en la cuenta del móvil una sola vez y solo si el monto coincide con el pedido.
create or replace function public.webhook_mp(token text, pago_id bigint, pago_mp_id text, monto_pagado numeric, estado_mp text default 'approved', medio_mp text default null) returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare p rodar.mp_pagos; m rodar.moviles;
begin
  if token is distinct from rodar.cfg('webhook_token') #>> '{}' then raise exception 'token inválido'; end if;
  select * into p from rodar.mp_pagos where id = pago_id and tipo = 'recarga' for update;
  if not found then raise exception 'El pago % no existe', pago_id; end if;
  if p.acreditado then return jsonb_build_object('ok', true, 'ya_acreditado', true); end if;
  if estado_mp <> 'approved' then
    update rodar.mp_pagos set estado = case when estado_mp in ('rejected', 'cancelled') then 'cancelado' else 'pendiente' end, mp_id = coalesce(mp_pagos.mp_id, pago_mp_id) where mp_pagos.id = p.id;
    return jsonb_build_object('ok', true, 'estado', estado_mp);
  end if;
  if abs(coalesce(monto_pagado, 0) - p.monto) > 0.01 then raise exception 'El monto pagado (%) no coincide con el pedido (%)', monto_pagado, p.monto; end if;
  update rodar.mp_pagos set estado = 'pagado', medio = coalesce(medio_mp, 'mercadopago'), mp_id = pago_mp_id, liberacion = rodar.hoy(), acreditado = true where mp_pagos.id = p.id;
  perform rodar.registrar_pago(p.movil_id, p.monto, 'Pago de base Mercado Pago #' || pago_mp_id, null, 'carga_mp');
  select * into m from rodar.moviles where id = p.movil_id;
  perform rodar.emitir_movil(p.movil_id);
  perform rodar.emit('panel', 'aviso', jsonb_build_object('texto', 'Móvil ' || m.numero || ' pagó la base: $' || p.monto));
  perform rodar.emit('movil-' || p.movil_id, 'pago_base', jsonb_build_object('monto', p.monto));
  return jsonb_build_object('ok', true);
end $$;

notify pgrst, 'reload schema';


-- ======== 18_alias_base.sql ========
-- Alias de Mercado Pago al que los móviles transfieren la base (si la central no puso otro).
do $$ begin
  perform rodar.cfg_set('mp', coalesce(rodar.cfg('mp', '{}'), '{}'::jsonb) || jsonb_build_object('alias_cobro', 'danderfertcesar.mp')
    ) where coalesce(rodar.cfg('mp', '{}') ->> 'alias_cobro', '') = '';
end $$;


-- ======== 19_turnos.sql ========
-- Orden de puesta en servicio y turnos (mañana / tarde / noche) en el mapa.
alter table rodar.moviles add column if not exists en_servicio_desde timestamp;

create or replace function rodar.trg_en_servicio() returns trigger language plpgsql as $t$
begin
  if new.estado in ('desconectado', 'fuera_servicio') then new.en_servicio_desde := null;
  elsif old.estado in ('desconectado', 'fuera_servicio') or new.en_servicio_desde is null then new.en_servicio_desde := coalesce(new.en_servicio_desde, rodar.ahora());
  end if;
  return new;
end $t$;
drop trigger if exists en_servicio on rodar.moviles;
create trigger en_servicio before update of estado on rodar.moviles for each row when (new.estado is distinct from old.estado) execute function rodar.trg_en_servicio();
-- Móviles que ya están en servicio al instalar: se toma la última señal como referencia.
update rodar.moviles set en_servicio_desde = coalesce(ultima_senal, rodar.ahora()) where estado not in ('desconectado', 'fuera_servicio') and en_servicio_desde is null;

create or replace function rodar.movil_publico(m rodar.moviles) returns jsonb language plpgsql stable as $$
#variable_conflict use_variable

declare cond text; ec jsonb; pen jsonb; z rodar.zonas;
begin
  select trim(nombre || ' ' || coalesce(apellido, '')) into cond from rodar.usuarios where id = m.conductor_id;
  ec := rodar.estado_cuenta(m);
  select jsonb_build_object('hasta', hasta, 'motivo', motivo) into pen from rodar.penalizaciones where movil_id = m.id and hasta > rodar.ahora() order by hasta desc limit 1;
  z := rodar.zona_de(m.lat, m.lng);
  return jsonb_build_object('id', m.id, 'numero', m.numero, 'patente', m.patente, 'marca', m.marca, 'modelo', m.modelo, 'color', m.color,
    'estado', m.estado, 'lat', m.lat, 'lng', m.lng, 'rumbo', m.rumbo, 'velocidad', m.velocidad, 'parada_id', m.parada_id, 'parada_ingreso', m.parada_ingreso,
    'ultima_senal', m.ultima_senal, 'conductor', cond, 'conductor_id', m.conductor_id, 'cuenta', ec ->> 'color', 'saldo', (ec ->> 'saldo')::numeric,
    'sin_saldo', (ec ->> 'sin_saldo')::boolean, 'bloqueado', (ec ->> 'bloqueado')::boolean, 'penalizado', pen, 'zona', z.nombre, 'habilitado', m.habilitado, 'simulado', m.simulado, 'en_servicio_desde', m.en_servicio_desde);
end $$;


-- ======== 20_mejoras_viajes.sql ========
-- ===================== Eliminar viajes (admin) y datos del conductor para clientes con cuenta =====================

-- Elimina un viaje del listado. Solo admin. No se puede si está ofrecido, confirmado o en curso (primero hay que anularlo o finalizarlo).
-- No toca la cuenta del móvil: los movimientos ya registrados (cuota o comisión del viaje) se conservan como estaban.
create or replace function public.r_viaje_borrar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.need(p_token, 'admin'); vid bigint := (p_q ->> 'id')::bigint; v rodar.viajes;
begin
  select * into v from rodar.viajes where id = vid;
  if not found then raise exception 'El viaje no existe'; end if;
  if v.estado in ('ofrecido', 'confirmado', 'en_curso') then
    raise exception 'El viaje #% está en curso. Anulalo o finalizalo antes de eliminarlo.', vid;
  end if;
  delete from rodar.viajes where id = vid;
  perform rodar.accion(u, 'viaje_eliminado', vid::text, 'Se eliminó el viaje #' || vid || ' (' || coalesce(v.estado, '') || ') · ' || coalesce(v.origen_dir, ''));
  perform rodar.emit('panel', 'viaje_baja', jsonb_build_object('id', vid));
  return jsonb_build_object('ok', true);
end $$;
grant execute on function public.r_viaje_borrar(text, jsonb, jsonb) to anon, authenticated;

-- Mis viajes (cliente con cuenta): ahora incluye el conductor y el color del auto, igual que el seguimiento de un pedido sin cuenta.
create or replace function public.r_cli_viajes(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c rodar.clientes := rodar.cliente_sesion(p_token); lim int := least(100, coalesce(rodar.n(p_q, 'limite'), 30)::int);
begin
  return coalesce((select jsonb_agg(x order by orden, creado desc) from (
    select v.id, v.creado, v.programado, v.estado, v.origen_dir, v.origen_ref, v.origen_lat, v.origen_lng, v.destino_dir, v.destino_lat, v.destino_lng,
      coalesce(v.monto, v.monto_estimado) monto, v.monto is not null monto_final, v.km, v.minutos, v.medio_pago, v.calificacion, v.inicio_at, v.fin_at, v.motivo_anulacion,
      m.numero movil_numero, m.patente, m.color movil_color, trim(coalesce(m.marca, '') || ' ' || coalesce(m.modelo, '')) movil,
      case when v.estado in ('confirmado', 'en_curso', 'finalizado') then nullif(trim(coalesce(u.nombre, '') || ' ' || coalesce(u.apellido, '')), '') end conductor,
      rodar.firma(v.id) k,
      case when v.estado in ('pendiente', 'ofrecido', 'confirmado', 'en_curso') then 0 when v.estado = 'reserva' then 1 else 2 end orden
    from rodar.viajes v left join rodar.moviles m on m.id = v.movil_id left join rodar.usuarios u on u.id = v.conductor_id
    where v.cliente_id = c.id and v.creado >= c.cuenta_creada - interval '1 minute'
    order by orden, v.creado desc limit lim) x), '[]');
end $$;

notify pgrst, 'reload schema';


-- ======== 21_billetera_reinicio.sql ========
-- ===================== Billetera virtual del conductor y borrado total que conserva zonas y paradas =====================

-- Billetera virtual propia del conductor (alias o CVU/CBU donde recibe pagos).
alter table rodar.usuarios add column if not exists billetera_tipo text;
alter table rodar.usuarios add column if not exists billetera_alias text;

-- Sin datos en el cuerpo devuelve la billetera guardada; con "alias" la guarda (alias vacío = quitarla).
create or replace function public.r_cond_billetera(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); al text; tp text;
begin
  if p_b ? 'alias' then
    al := regexp_replace(trim(coalesce(p_b ->> 'alias', '')), '^@', '');
    tp := nullif(trim(coalesce(p_b ->> 'tipo', '')), '');
    if al = '' then
      update rodar.usuarios set billetera_tipo = null, billetera_alias = null where id = u.id;
    else
      if al !~ '^[A-Za-z0-9._-]{6,40}$' and al !~ '^[0-9]{22}$' then
        raise exception 'El alias debe tener entre 6 y 40 caracteres (letras, números, punto o guion), o ser un CVU/CBU de 22 dígitos';
      end if;
      if tp is not null and tp not in ('mercadopago', 'uala', 'naranja_x', 'brubank', 'personal_pay', 'otra') then raise exception 'Billetera no válida'; end if;
      update rodar.usuarios set billetera_tipo = coalesce(tp, 'otra'), billetera_alias = al where id = u.id;
    end if;
    select * into u from rodar.usuarios where id = u.id;
  end if;
  return jsonb_build_object('tipo', u.billetera_tipo, 'alias', u.billetera_alias);
end $$;
grant execute on function public.r_cond_billetera(text, jsonb, jsonb) to anon, authenticated;

-- Borrar todo el sistema: ahora se conservan las zonas y paradas, salvo que el administrador pida borrarlas (zonas = 'borrar').
create or replace function public.r_sistema_reiniciar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.need(p_token, 'admin'); t text; borrar_zonas boolean := lower(coalesce(p_b ->> 'zonas', 'conservar')) = 'borrar';
  tablas text[] := array['viajes', 'clientes', 'cliente_domicilios', 'negativos', 'sesiones_clientes', 'moviles', 'movil_conductores',
    'penalizaciones', 'cuenta_movimientos', 'mp_pagos', 'mp_saldo_mov', 'solicitudes_conductor', 'acciones_usuarios', 'eventos_moviles',
    'moviles_historial', 'posiciones', 'soporte_conv', 'soporte_msg', 'chat_conv', 'chat_msg', 'reportes', 'reporte_historial',
    'novedades_vistas', 'conexion_diaria', 'mensajes_flota', 'limite_pedidos', 'sim_estado', 'direcciones_conocidas', 'docs_generados',
    'corporativos'];
begin
  if not rodar.verificar(coalesce(p_b ->> 'password', ''), u.password_hash) then raise exception 'La contraseña no es correcta'; end if;
  if upper(trim(coalesce(p_b ->> 'confirmacion', ''))) <> 'BORRAR TODO' then raise exception 'Escribí BORRAR TODO para confirmar'; end if;
  if borrar_zonas then tablas := tablas || array['zonas', 'zonas_peligrosas']; end if;
  foreach t in array tablas loop
    if to_regclass('rodar.' || t) is not null then execute format('truncate table rodar.%I restart identity cascade', t); end if;
  end loop;
  delete from rodar.sesiones where usuario_id <> u.id;
  delete from rodar.usuarios where id <> u.id;
  update rodar.usuarios set corporativo_id = null where id = u.id;
  perform rodar.cfg_set('simulador', '{"flota":false,"demanda":false}');
  perform rodar.accion(u, 'sistema_reiniciado', null, case when borrar_zonas then 'Se borraron todos los datos, incluidas las zonas y paradas' else 'Se borraron todos los datos (se conservaron zonas y paradas)' end);
  return jsonb_build_object('ok', true, 'zonas_borradas', borrar_zonas);
end $$;

notify pgrst, 'reload schema';


-- ======== 22_destino_obligatorio.sql ========
-- ===================== "¿A dónde vas?" obligatorio en los pedidos de pasajeros (con y sin cuenta) =====================
-- Los pedidos de operadores, de la calle y de la centralita siguen pudiendo no tener destino.

create or replace function public.r_pub_viaje(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare tel text := regexp_replace(coalesce(p_b ->> 'telefono', ''), '\D', '', 'g'); corp bigint; medio text := coalesce(rodar.t(p_b, 'medio_pago'), 'efectivo'); ids bigint[]; s rodar.usuarios;
begin
  if rodar.t(p_b, 'destino_dir') is null or p_b ->> 'destino_lat' is null then raise exception 'Indicá a dónde vas'; end if;
  if (select count(*) from rodar.limite_pedidos where clave = tel and ts > now() - interval '10 minutes') >= 5 then raise exception 'Demasiados pedidos seguidos. Esperá unos minutos o llamá a la central.'; end if;
  if (select count(*) from rodar.limite_pedidos where ts > now() - interval '1 minute') >= 40 then raise exception 'Hay demasiados pedidos en este momento, probá en un minuto.'; end if;
  insert into rodar.limite_pedidos(clave) values (tel);
  if length(tel) < 8 then raise exception 'Ingresá un teléfono válido'; end if;
  if rodar.t(p_b, 'origen_dir') is null or p_b ->> 'origen_lat' is null then raise exception 'Indicá el origen en el mapa o buscá la dirección'; end if;
  if rodar.t(p_b, 'token') is not null then
    select u.* into s from rodar.sesiones x join rodar.usuarios u on u.id = x.usuario_id where x.token = p_b ->> 'token' and x.activa;
    if s.corporativo_id is not null then corp := s.corporativo_id; medio := 'cuenta_corriente'; end if;
  end if;
  ids := rodar.crear_viaje(p_b || jsonb_build_object('telefono', tel, 'alias', p_b ->> 'nombre', 'canal', 'web', 'medio_pago', medio, 'corporativo_id', corp, 'pin_requerido', true,
    'cantidad_moviles', 1, 'estado', 'pendiente', 'movil_id', null, 'conductor_id', null, 'programado', null, 'monto_fijo', null), null);
  perform rodar.procesar();
  return jsonb_build_object('id', ids[1], 'k', rodar.firma(ids[1]), 'canal', rodar.topico('viaje-' || ids[1] || '-' || rodar.firma(ids[1])));
end $$;

create or replace function public.r_cli_viaje(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c rodar.clientes := rodar.cliente_sesion(p_token); prog timestamp := rodar.ts(p_b, 'programado'); medio text := coalesce(rodar.t(p_b, 'medio_pago'), c.medio_pago_pref, 'efectivo'); ids bigint[];
begin
  if rodar.t(p_b, 'destino_dir') is null or p_b ->> 'destino_lat' is null then raise exception 'Indicá a dónde vas'; end if;
  if rodar.t(p_b, 'origen_dir') is null or p_b ->> 'origen_lat' is null then raise exception 'Indicá el origen en el mapa o buscá la dirección'; end if;
  if prog is not null then
    if prog < rodar.ahora() + interval '15 minutes' then raise exception 'Para reservar elegí un horario con al menos 15 minutos de anticipación (o pedí "Ahora").'; end if;
    if prog > rodar.ahora() + interval '60 days' then raise exception 'Se puede reservar hasta 60 días antes'; end if;
    if (select count(*) from rodar.viajes where cliente_id = c.id and estado = 'reserva') >= 10 then raise exception 'Tenés muchas reservas pendientes. Cancelá alguna o llamá a la central.'; end if;
  elsif (select count(*) from rodar.viajes where cliente_id = c.id and estado in ('pendiente', 'ofrecido', 'confirmado', 'en_curso')) >= 2 then
    raise exception 'Ya tenés viajes en curso. Si necesitás otro móvil, llamá a la central.';
  end if;
  perform rodar.limitar('cli:' || c.id, 6, interval '10 minutes', 'Demasiados pedidos seguidos. Esperá unos minutos o llamá a la central.');
  ids := rodar.crear_viaje(p_b || jsonb_build_object('telefono', c.telefono, 'alias', c.alias, 'canal', 'aplicacion', 'medio_pago', medio, 'pin_requerido', true,
    'cantidad_moviles', 1, 'estado', 'pendiente', 'movil_id', null, 'conductor_id', null, 'monto_fijo', null, 'corporativo_id', null, 'a_oferta', false, 'origen_tipo', 'central', 'datos_movil', null,
    'programado', case when prog is null then null else to_char(prog, 'YYYY-MM-DD HH24:MI:SS') end), null);
  update rodar.clientes set medio_pago_pref = medio where id = c.id;
  perform rodar.procesar();
  return jsonb_build_object('id', ids[1], 'k', rodar.firma(ids[1]), 'reserva', prog is not null, 'canal', rodar.topico('viaje-' || ids[1] || '-' || rodar.firma(ids[1])));
end $$;

notify pgrst, 'reload schema';


-- ======== 23_perfil_conductor.sql ========
-- ===================== El conductor actualiza sus propios datos desde la app =====================
-- Solo datos personales de contacto. No se tocan el DNI, el usuario, la clave, los roles ni los datos bancarios (esos tienen su propia pantalla).

create or replace function public.r_cond_perfil(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token);
begin
  perform rodar.movil_sesion(p_token);
  return jsonb_build_object('documento', u.documento, 'nombre', u.nombre, 'apellido', u.apellido, 'telefono', u.telefono, 'email', u.email,
    'tel_recupero', u.tel_recupero, 'email_recupero', u.email_recupero);
end $$;

create or replace function public.r_cond_perfil_guardar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); nom text := rodar.t(p_b, 'nombre'); em text := lower(rodar.t(p_b, 'email')); emr text := lower(rodar.t(p_b, 'email_recupero'));
  tel text := rodar.t(p_b, 'telefono'); telr text := rodar.t(p_b, 'tel_recupero');
begin
  perform rodar.movil_sesion(p_token);
  if nom is null then raise exception 'Escribí tu nombre'; end if;
  if em is not null and em !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Revisá el email: no parece válido'; end if;
  if emr is not null and emr !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Revisá el email de recupero: no parece válido'; end if;
  if tel is not null and length(regexp_replace(tel, '\D', '', 'g')) < 8 then raise exception 'Revisá el teléfono: tiene que incluir la característica'; end if;
  if telr is not null and length(regexp_replace(telr, '\D', '', 'g')) < 8 then raise exception 'Revisá el teléfono de recupero: tiene que incluir la característica'; end if;
  update rodar.usuarios set nombre = left(nom, 60), apellido = left(coalesce(rodar.t(p_b, 'apellido'), ''), 60), telefono = left(tel, 30), email = left(em, 120),
    tel_recupero = left(telr, 30), email_recupero = left(emr, 120) where id = u.id;
  perform rodar.accion(u, 'perfil_conductor', u.documento, 'El conductor actualizó sus datos desde la app');
  return jsonb_build_object('ok', true);
end $$;

notify pgrst, 'reload schema';


-- ======== 24_soporte_borrar.sql ========
-- ===================== Soporte / Reclamos: eliminar conversaciones =====================
-- Elimina una conversación con todos sus mensajes (operador o admin).
create or replace function public.r_soporte_borrar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.need(p_token, 'operador'); cid bigint := (p_q ->> 'id')::bigint; c rodar.soporte_conv;
begin
  select * into c from rodar.soporte_conv where id = cid;
  if not found then raise exception 'La conversación no existe'; end if;
  delete from rodar.soporte_msg where conv_id = cid;
  delete from rodar.soporte_conv where id = cid;
  perform rodar.accion(u, 'soporte_eliminado', cid::text, 'Se eliminó la conversación de soporte #' || cid || ' (' || coalesce(c.asunto, '') || ')');
  perform rodar.emit('panel', 'soporte', jsonb_build_object('conv', cid, 'borrada', true));
  return jsonb_build_object('ok', true);
end $$;

-- Elimina de una vez todas las conversaciones cerradas.
create or replace function public.r_soporte_borrar_cerradas(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.need(p_token, 'operador'); n int;
begin
  delete from rodar.soporte_msg where conv_id in (select id from rodar.soporte_conv where cerrada);
  delete from rodar.soporte_conv where cerrada;
  get diagnostics n = row_count;
  if n > 0 then perform rodar.accion(u, 'soporte_eliminado', null, 'Se eliminaron ' || n || ' conversaciones de soporte cerradas'); end if;
  perform rodar.emit('panel', 'soporte', jsonb_build_object('borradas', n));
  return jsonb_build_object('ok', true, 'borradas', n);
end $$;

grant execute on function public.r_soporte_borrar(text, jsonb, jsonb), public.r_soporte_borrar_cerradas(text, jsonb, jsonb) to anon, authenticated;
notify pgrst, 'reload schema';


-- ======== 25_push.sql ========
-- ===================== Notificaciones push para la app del conductor =====================
-- Con el celular bloqueado o la app cerrada, el navegador no recibe el tiempo real. Las notificaciones push sí llegan:
-- la base encola el aviso y llama a la Edge Function "push" (con pg_net), que lo entrega a cada celular suscripto.
-- Las claves VAPID y el secreto se guardan en rodar.config ('push'); nunca se publican en este archivo.
create extension if not exists pg_net;

create table if not exists rodar.push_subs (
  id bigint generated by default as identity primary key,
  endpoint text not null unique, p256dh text not null, auth text not null,
  token text, movil_id bigint, usuario_id bigint, ua text,
  activa boolean default true, creado timestamp, actualizado timestamp
);
create index if not exists ix_push_subs_movil on rodar.push_subs(movil_id) where activa;

create table if not exists rodar.push_cola (
  id bigint generated by default as identity primary key,
  clave text, msg jsonb, subs jsonb, estado text default 'pendiente', resultado jsonb, creado timestamp default now()
);
create index if not exists ix_push_cola_clave on rodar.push_cola(clave, creado);
revoke all on rodar.push_subs, rodar.push_cola from anon, authenticated;

-- Encola y dispara un aviso. p_subs: lista de suscripciones; p_clave evita repetir el mismo aviso (ej. oferta abierta).
create or replace function rodar.push_enviar(p_subs jsonb, p_msg jsonb, p_clave text default null) returns void language plpgsql as $$
#variable_conflict use_variable

declare c jsonb := rodar.cfg('push', '{}'); nid bigint;
begin
  if coalesce(c ->> 'url', '') = '' or coalesce(c ->> 'privada', '') = '' then return; end if;
  if p_subs is null or jsonb_array_length(p_subs) = 0 then return; end if;
  if p_clave is not null and exists(select 1 from rodar.push_cola where clave = p_clave and creado > now() - interval '15 minutes') then return; end if;
  insert into rodar.push_cola(clave, msg, subs) values (p_clave, p_msg, p_subs) returning id into nid;
  perform net.http_post(url := c ->> 'url', body := jsonb_build_object('id', nid),
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-push-secreto', c ->> 'secreto'), timeout_milliseconds := 8000);
exception when others then null; -- un aviso que falla nunca frena la operación
end $$;

-- Suscripciones vigentes de un móvil (solo celulares con la sesión abierta)
create or replace function rodar.push_subs_movil(p_movil bigint) returns jsonb language sql stable as $$
  select coalesce(jsonb_agg(jsonb_build_object('endpoint', p.endpoint, 'p256dh', p.p256dh, 'auth', p.auth)), '[]'::jsonb)
  from rodar.push_subs p join rodar.sesiones s on s.token = p.token and s.activa
  where p.activa and p.movil_id = p_movil
$$;
create or replace function rodar.push_subs_flota() returns jsonb language sql stable as $$
  select coalesce(jsonb_agg(jsonb_build_object('endpoint', p.endpoint, 'p256dh', p.p256dh, 'auth', p.auth)), '[]'::jsonb)
  from rodar.push_subs p join rodar.sesiones s on s.token = p.token and s.activa where p.activa
$$;

-- Traduce los eventos del tiempo real que le importan al conductor en un aviso push
create or replace function rodar.push_evento(p_topic text, p_evento text, p_payload jsonb) returns void language plpgsql as $$
#variable_conflict use_variable

declare mid bigint; subs jsonb; msg jsonb; clave text; d jsonb := coalesce(p_payload, '{}');
  pesos text := case when (d ->> 'monto_estimado') is not null then ' · $ ' || replace(to_char(round((d ->> 'monto_estimado')::numeric), 'FM999G999G999'), ',', '.') else '' end;
begin
  if p_topic = 'flota' and p_evento = 'mensaje_flota' then
    subs := rodar.push_subs_flota();
    msg := jsonb_build_object('tipo', 'flota', 'titulo', '📢 Mensaje de la central', 'cuerpo', d ->> 'texto', 'url', 'conductor.html#mensaje', 'tag', 'rodar-flota', 'ttl', 86400, 'fijo', true);
    perform rodar.push_enviar(subs, msg); return;
  end if;
  if p_topic !~ '^movil-\d+$' or p_evento not in ('oferta', 'oferta_abierta', 'oferta_cancelada', 'asignado', 'mensaje') then return; end if;
  mid := substr(p_topic, 7)::bigint;
  if not exists(select 1 from rodar.push_subs where movil_id = mid and activa) then return; end if;
  subs := rodar.push_subs_movil(mid);
  msg := case p_evento
    when 'oferta' then jsonb_build_object('tipo', 'oferta', 'titulo', '🚕 Nuevo viaje #' || (d ->> 'id'), 'cuerpo', coalesce(d ->> 'origen_dir', '') || coalesce(' → ' || (d ->> 'destino_dir'), '') || pesos || E'\nTocá para aceptarlo',
      'url', 'conductor.html#oferta', 'tag', 'rodar-oferta', 'ttl', greatest(10, coalesce((d ->> 'segundos')::int, 20)), 'fijo', true, 'viaje', d ->> 'id')
    when 'oferta_abierta' then jsonb_build_object('tipo', 'oferta', 'titulo', '📣 Viaje a oferta #' || (d ->> 'id'), 'cuerpo', coalesce(d ->> 'origen_dir', '') || pesos || E'\nTocá para postularte',
      'url', 'conductor.html#oferta', 'tag', 'rodar-abierta-' || (d ->> 'id'), 'ttl', 60, 'viaje', d ->> 'id')
    when 'oferta_cancelada' then jsonb_build_object('tipo', 'cerrar', 'cerrar', 'rodar-oferta', 'titulo', 'Viaje reasignado', 'cuerpo', 'El viaje ofrecido ya no está disponible', 'tag', 'rodar-oferta', 'ttl', 30, 'silencio', true, 'url', 'conductor.html')
    when 'asignado' then jsonb_build_object('tipo', 'asignado', 'titulo', '✅ Te asignaron un viaje', 'cuerpo', 'La central te asignó el viaje #' || coalesce(d ->> 'id', '') || E'\nTocá para ver a dónde ir', 'url', 'conductor.html', 'tag', 'rodar-asignado', 'ttl', 600, 'fijo', true)
    when 'mensaje' then jsonb_build_object('tipo', 'mensaje', 'titulo', '💬 Mensaje de la ' || coalesce(d ->> 'de', 'Central'), 'cuerpo', coalesce(d ->> 'texto', '') || E'\nTocá para responder', 'url', 'conductor.html#soporte', 'tag', 'rodar-soporte', 'ttl', 86400, 'fijo', true)
  end;
  clave := case when p_evento = 'oferta_abierta' then 'abierta-' || (d ->> 'id') || '-' || mid end;
  perform rodar.push_enviar(subs, msg, clave);
exception when others then null;
end $$;

-- El emisor del tiempo real ahora también dispara los avisos push
create or replace function rodar.emit(p_topic text, p_evento text, p_payload jsonb) returns void language plpgsql as $$
#variable_conflict use_variable

begin
  begin
    perform realtime.send(coalesce(p_payload, '{}'::jsonb), p_evento, rodar.topico(p_topic), false);
  exception when others then null; -- sin Realtime disponible: se ignora (los clientes también consultan periódicamente)
  end;
  if p_evento in ('oferta', 'oferta_abierta', 'oferta_cancelada', 'asignado', 'mensaje', 'mensaje_flota') then
    perform rodar.push_evento(p_topic, p_evento, p_payload);
  end if;
end $$;

-- App del conductor: clave pública y alta de la suscripción de este celular
create or replace function public.r_cond_push(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare m rodar.moviles := rodar.movil_sesion(p_token); u rodar.usuarios := rodar.usuario(p_token); s jsonb := p_b -> 'sub'; c jsonb := rodar.cfg('push', '{}');
begin
  if s is null then return jsonb_build_object('publica', c ->> 'publica'); end if;
  if coalesce(s ->> 'endpoint', '') !~ '^https://' or coalesce(s #>> '{keys,p256dh}', '') = '' or coalesce(s #>> '{keys,auth}', '') = '' then raise exception 'Suscripción inválida'; end if;
  insert into rodar.push_subs(endpoint, p256dh, auth, token, movil_id, usuario_id, ua, activa, creado, actualizado)
  values (s ->> 'endpoint', s #>> '{keys,p256dh}', s #>> '{keys,auth}', p_token, m.id, u.id, left(p_b ->> 'ua', 300), true, rodar.ahora(), rodar.ahora())
  on conflict (endpoint) do update set p256dh = excluded.p256dh, auth = excluded.auth, token = excluded.token, movil_id = excluded.movil_id,
    usuario_id = excluded.usuario_id, ua = excluded.ua, activa = true, actualizado = excluded.actualizado;
  return jsonb_build_object('ok', true);
end $$;

-- Edge Function "push": toma un aviso de la cola (con el secreto compartido) y después informa las suscripciones vencidas
create or replace function public.r_push_tomar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c jsonb := rodar.cfg('push', '{}'); q rodar.push_cola;
begin
  if coalesce(c ->> 'secreto', '') = '' or p_b ->> 'secreto' is distinct from c ->> 'secreto' then raise exception 'No autorizado'; end if;
  update rodar.push_cola set estado = 'enviando' where id = (p_b ->> 'id')::bigint and estado = 'pendiente' returning * into q;
  if q.id is null then return jsonb_build_object('nada', true); end if;
  return jsonb_build_object('msg', q.msg, 'subs', q.subs, 'publica', c ->> 'publica', 'privada', c ->> 'privada', 'sujeto', coalesce(c ->> 'sujeto', 'mailto:soporte@remisestoque.com'));
end $$;
create or replace function public.r_push_resultado(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c jsonb := rodar.cfg('push', '{}');
begin
  if coalesce(c ->> 'secreto', '') = '' or p_b ->> 'secreto' is distinct from c ->> 'secreto' then raise exception 'No autorizado'; end if;
  update rodar.push_cola set estado = 'enviado', resultado = p_b -> 'resultado' where id = (p_b ->> 'id')::bigint;
  update rodar.push_subs set activa = false, actualizado = rodar.ahora()
    where endpoint in (select jsonb_array_elements_text(coalesce(p_b -> 'vencidas', '[]'::jsonb)));
  return jsonb_build_object('ok', true);
end $$;

grant execute on function public.r_cond_push(text, jsonb, jsonb), public.r_push_tomar(text, jsonb, jsonb), public.r_push_resultado(text, jsonb, jsonb) to anon, authenticated;
alter function rodar.push_enviar(jsonb, jsonb, text) set search_path = rodar, public, extensions;
alter function rodar.push_evento(text, text, jsonb) set search_path = rodar, public, extensions;
alter function rodar.emit(text, text, jsonb) set search_path = rodar, public, extensions;
notify pgrst, 'reload schema';


-- ======== 26_push_pasajero.sql ========
-- ===================== Notificaciones push para el pasajero =====================
-- Avisa al pasajero con cuenta (celular bloqueado o app cerrada): remís en camino, remís en la puerta, viaje terminado o cancelado.
alter table rodar.push_subs add column if not exists cliente_id bigint;
alter table rodar.push_subs add column if not exists app text default 'conductor';
create index if not exists ix_push_subs_cliente on rodar.push_subs(cliente_id) where activa;

create or replace function rodar.push_subs_cliente(p_cliente bigint) returns jsonb language sql stable as $$
  select coalesce(jsonb_agg(jsonb_build_object('endpoint', p.endpoint, 'p256dh', p.p256dh, 'auth', p.auth)), '[]'::jsonb)
  from rodar.push_subs p join rodar.sesiones_clientes s on s.token = p.token and s.activa
  where p.activa and p.cliente_id = p_cliente
$$;

create or replace function rodar.push_pasajero(p_viaje bigint) returns void language plpgsql as $$
#variable_conflict use_variable

declare v rodar.viajes; m rodar.moviles; msg jsonb; clave text; url text; movil text;
begin
  select * into v from rodar.viajes where id = p_viaje;
  if v.id is null or v.cliente_id is null then return; end if;
  if not exists(select 1 from rodar.push_subs where cliente_id = v.cliente_id and activa) then return; end if;
  select * into m from rodar.moviles where id = v.movil_id;
  movil := case when m.id is not null then 'Móvil ' || m.numero || coalesce(' · ' || nullif(trim(coalesce(m.marca, '') || ' ' || coalesce(m.modelo, '') || ' ' || coalesce(m.color, '')), ''), '') || coalesce(' · ' || m.patente, '') else '' end;
  url := 'pasajero.html#/seguimiento/' || v.id || '?k=' || rodar.firma(v.id);
  if v.estado = 'confirmado' and v.llegada_at is not null then
    clave := 'pas-' || v.id || '-llego';
    msg := jsonb_build_object('titulo', '📍 Tu remís llegó', 'cuerpo', movil || E'\nTe está esperando en ' || coalesce(v.origen_dir, 'la dirección indicada'), 'fijo', true, 'ttl', 900);
  elsif v.estado = 'confirmado' then
    clave := 'pas-' || v.id || '-camino';
    msg := jsonb_build_object('titulo', '🚕 Tu remís está en camino', 'cuerpo', movil || E'\nTocá para seguirlo en el mapa', 'ttl', 1800);
  elsif v.estado = 'finalizado' then
    clave := 'pas-' || v.id || '-fin';
    msg := jsonb_build_object('titulo', '✅ ¡Llegaste!', 'cuerpo', case when coalesce(v.monto, 0) > 0 then 'Total: $ ' || replace(to_char(round(v.monto), 'FM999G999G999'), ',', '.') || '. ' else '' end || '¡Gracias por viajar con nosotros!', 'ttl', 3600);
  elsif v.estado = 'anulado' then
    clave := 'pas-' || v.id || '-anulado';
    msg := jsonb_build_object('titulo', 'Viaje cancelado', 'cuerpo', 'Tu viaje #' || v.id || ' fue cancelado. Si lo necesitás, pedí otro desde la app.', 'ttl', 3600);
  else
    return;
  end if;
  msg := msg || jsonb_build_object('tipo', 'pasajero', 'url', url, 'tag', 'rodar-viaje-' || v.id, 'viaje', v.id);
  perform rodar.push_enviar(rodar.push_subs_cliente(v.cliente_id), msg, clave);
exception when others then null;
end $$;

-- El emisor del tiempo real también avisa al pasajero cuando cambia su viaje
create or replace function rodar.emit(p_topic text, p_evento text, p_payload jsonb) returns void language plpgsql as $$
#variable_conflict use_variable

begin
  begin
    perform realtime.send(coalesce(p_payload, '{}'::jsonb), p_evento, rodar.topico(p_topic), false);
  exception when others then null; -- sin Realtime disponible: se ignora (los clientes también consultan periódicamente)
  end;
  if p_evento in ('oferta', 'oferta_abierta', 'oferta_cancelada', 'asignado', 'mensaje', 'mensaje_flota') then
    perform rodar.push_evento(p_topic, p_evento, p_payload);
  elsif p_evento = 'viaje' and p_topic like 'viaje-%' then
    perform rodar.push_pasajero(nullif(substring(p_topic from '^viaje-(\d+)-'), '')::bigint);
  end if;
end $$;

-- App del pasajero: clave pública y alta de la suscripción de este celular
create or replace function public.r_cli_push(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare c rodar.clientes := rodar.cliente_sesion(p_token); s jsonb := p_b -> 'sub'; k jsonb := rodar.cfg('push', '{}');
begin
  if s is null then return jsonb_build_object('publica', k ->> 'publica'); end if;
  if coalesce(s ->> 'endpoint', '') !~ '^https://' or coalesce(s #>> '{keys,p256dh}', '') = '' or coalesce(s #>> '{keys,auth}', '') = '' then raise exception 'Suscripción inválida'; end if;
  insert into rodar.push_subs(endpoint, p256dh, auth, token, movil_id, usuario_id, cliente_id, app, ua, activa, creado, actualizado)
  values (s ->> 'endpoint', s #>> '{keys,p256dh}', s #>> '{keys,auth}', p_token, null, null, c.id, 'pasajero', left(p_b ->> 'ua', 300), true, rodar.ahora(), rodar.ahora())
  on conflict (endpoint) do update set p256dh = excluded.p256dh, auth = excluded.auth, token = excluded.token, movil_id = null, usuario_id = null,
    cliente_id = excluded.cliente_id, app = 'pasajero', ua = excluded.ua, activa = true, actualizado = excluded.actualizado;
  return jsonb_build_object('ok', true);
end $$;

-- La app del conductor marca su suscripción como de conductor (el mismo celular puede usar las dos)
create or replace function public.r_cond_push(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare m rodar.moviles := rodar.movil_sesion(p_token); u rodar.usuarios := rodar.usuario(p_token); s jsonb := p_b -> 'sub'; c jsonb := rodar.cfg('push', '{}');
begin
  if s is null then return jsonb_build_object('publica', c ->> 'publica'); end if;
  if coalesce(s ->> 'endpoint', '') !~ '^https://' or coalesce(s #>> '{keys,p256dh}', '') = '' or coalesce(s #>> '{keys,auth}', '') = '' then raise exception 'Suscripción inválida'; end if;
  insert into rodar.push_subs(endpoint, p256dh, auth, token, movil_id, usuario_id, cliente_id, app, ua, activa, creado, actualizado)
  values (s ->> 'endpoint', s #>> '{keys,p256dh}', s #>> '{keys,auth}', p_token, m.id, u.id, null, 'conductor', left(p_b ->> 'ua', 300), true, rodar.ahora(), rodar.ahora())
  on conflict (endpoint) do update set p256dh = excluded.p256dh, auth = excluded.auth, token = excluded.token, movil_id = excluded.movil_id,
    usuario_id = excluded.usuario_id, cliente_id = null, app = 'conductor', ua = excluded.ua, activa = true, actualizado = excluded.actualizado;
  return jsonb_build_object('ok', true);
end $$;

grant execute on function public.r_cli_push(text, jsonb, jsonb), public.r_cond_push(text, jsonb, jsonb) to anon, authenticated;
alter function rodar.push_pasajero(bigint) set search_path = rodar, public, extensions;
alter function rodar.emit(text, text, jsonb) set search_path = rodar, public, extensions;
notify pgrst, 'reload schema';


-- ======== 27_radio.sql ========
-- ===================== Radio (PTT) entre la central y los móviles =====================
-- El audio se guarda en la base y por tiempo real solo viaja un aviso corto con el número de mensaje.
-- Así no se pierde por el límite de tamaño del tiempo real y funciona igual en la app Android y en el navegador.
create table if not exists rodar.radio_msgs (
  id bigint generated by default as identity primary key,
  de text, movil_id bigint, usuario_id bigint, mime text, audio text, creado timestamp default now()
);
create index if not exists ix_radio_creado on rodar.radio_msgs(creado);
revoke all on rodar.radio_msgs from anon, authenticated;

create or replace function public.r_radio_enviar(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); s rodar.sesiones; a text := p_b ->> 'audio'; nid bigint; m rodar.moviles;
begin
  if coalesce(a, '') !~ '^data:audio/' then raise exception 'Audio inválido'; end if;
  if length(a) > 1500000 then raise exception 'El mensaje es demasiado largo (máximo 30 segundos)'; end if;
  select * into s from rodar.sesiones where token = p_token;
  if s.movil_id is not null then select * into m from rodar.moviles where id = s.movil_id; end if;
  -- los audios viejos se vacían (quedan solo los de la última hora)
  update rodar.radio_msgs set audio = null where audio is not null and creado < now() - interval '1 hour';
  insert into rodar.radio_msgs(de, movil_id, usuario_id, mime, audio)
  values (coalesce(nullif(left(p_b ->> 'de', 120), ''), case when m.id is not null then 'Móvil ' || m.numero else trim(u.nombre || ' ' || coalesce(u.apellido, '')) end),
          m.id, u.id, left(p_b ->> 'mime', 60), a) returning id into nid;
  perform rodar.emit('radio', 'radio', jsonb_build_object('id', nid, 'de', (select de from rodar.radio_msgs where id = nid), 'movil', m.numero));
  return jsonb_build_object('ok', true, 'id', nid);
end $$;

create or replace function public.r_radio_audio(p_token text default null, p_q jsonb default '{}', p_b jsonb default '{}') returns jsonb
language plpgsql security definer set search_path = rodar, public, extensions as $$
#variable_conflict use_variable

declare u rodar.usuarios := rodar.usuario(p_token); r rodar.radio_msgs;
begin
  select * into r from rodar.radio_msgs where id = (p_q ->> 'id')::bigint;
  if r.id is null or r.audio is null then raise exception 'El audio ya no está disponible'; end if;
  return jsonb_build_object('id', r.id, 'de', r.de, 'mime', r.mime, 'audio', r.audio);
end $$;

grant execute on function public.r_radio_enviar(text, jsonb, jsonb), public.r_radio_audio(text, jsonb, jsonb) to anon, authenticated;
notify pgrst, 'reload schema';
